type LocalApi = { configuracao: () => Promise<any>; salvarConfiguracao: (dados: any) => Promise<any>; testarServidor: (dados: any) => Promise<any>; listarOperadores: () => Promise<Operador[]>; registrarOperador: (dados: Omit<Operador, 'perfil'>) => Promise<any>; entrarOperador: (email: string) => Promise<any>; dashboard: (filtro?: { inicio?: string; fim?: string }) => Promise<any>; listarCasos: (termo?: string) => Promise<any[]>; carregarCaso: (id: string) => Promise<any>; listarVitimasCaso: (id: string) => Promise<any[]>; adicionarVitima: (dados: any) => Promise<any>; salvarVitima: (dados: any) => Promise<any>; listarFotos: (id: string) => Promise<any[]>; buscarFotos: (termo?: string) => Promise<any[]>; selecionarImagemConfronto: () => Promise<any>; obterCaminhoArquivoArrastado: (arquivo: File) => string; confrontarImagem: (caminho: string, limiar?: number) => Promise<any>; abrirFoto: (caminho: string) => Promise<any>; adicionarFoto: (id: string, metadados?: { nome?: string; dataTalao?: string; talao?: string; operador?: string }) => Promise<any>; registrarConsentimentoFoto: (dados: any) => Promise<any>; listarAuditoriaCasos: (termo?: string) => Promise<any[]>; historicoCaso: (id: string) => Promise<any[]>; corrigirCaso: (dados: any) => Promise<any>; salvarDesfechoOperacional: (dados: any) => Promise<any>; salvarPainelArvore: (dados: any) => Promise<any>; auditoria: () => Promise<any[]>; buscarPessoasF2: (dados: any) => Promise<any>; criarPessoaF2: (dados: any) => Promise<any>; listarAnalisesF2: (idPessoa: string) => Promise<any>; criarAnaliseF2: (dados: any) => Promise<any>; listarEventosF2: (idPessoa: string) => Promise<any>; criarQualificacaoF2: (dados: any) => Promise<any>; criarPistaF2: (dados: any) => Promise<any>; listarProducaoConsolidada?: (filtro?: { inicio?: string; fim?: string }) => Promise<any> };
declare global { interface Window { cabineVerdeLocal?: LocalApi } }
const api: LocalApi = window.cabineVerdeLocal || { configuracao: async () => ({ modo: 'central', apiBaseUrl: 'http://127.0.0.1' }), salvarConfiguracao: async (dados) => dados, testarServidor: async () => ({ ok: false }), listarOperadores: async () => [], registrarOperador: async () => ({ ok: false }), entrarOperador: async () => ({ ok: false }), dashboard: async () => ({ totalCasos: 0, incompletos: 0, porStatus: [], porPrioridade: [], observacoes: 0 }), listarCasos: async () => [], carregarCaso: async () => null, listarVitimasCaso: async () => [], adicionarVitima: async () => ({ ok: false }), salvarVitima: async () => ({ ok: false }), listarFotos: async () => [], buscarFotos: async () => [], selecionarImagemConfronto: async () => null, confrontarImagem: async () => ({ ok: false }), abrirFoto: async () => ({ ok: false }), adicionarFoto: async () => null, registrarConsentimentoFoto: async () => ({ ok: false }), listarAuditoriaCasos: async () => [], historicoCaso: async () => [], corrigirCaso: async () => ({ ok: false }), salvarDesfechoOperacional: async () => ({ ok: false }), salvarPainelArvore: async () => ({ ok: false }), auditoria: async () => [], buscarPessoasF2: async () => ({ ok: false, pessoas: [] }), criarPessoaF2: async () => ({ ok: false }), listarAnalisesF2: async () => ({ ok: false, analises: [] }), criarAnaliseF2: async () => ({ ok: false }), listarEventosF2: async () => ({ ok: false, eventos: [] }), criarQualificacaoF2: async () => ({ ok: false }), criarPistaF2: async () => ({ ok: false }) };

function Cartao({ titulo, valor, detalhe }: { titulo: string; valor: string | number; detalhe?: string }) { return <article className="cartao"><span>{titulo}</span><strong>{valor}</strong>{detalhe && <small>{detalhe}</small>}</article>; }
function Dashboard() { const [dados, setDados] = useState<any>(); useEffect(() => { api.dashboard().then(setDados); }, []); if (!dados) return <p className="carregando">Carregando indicadores locais...</p>; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Visão operacional</p><h2>Dashboard</h2><p>Leitura consolidada do banco local da Cabine Verde.</p></div></div><div className="grade-cartoes"><Cartao titulo="Casos" valor={dados.totalCasos} detalhe="registros no banco local" /><Cartao titulo="Incompletos" valor={dados.incompletos} detalhe="podem ser corrigidos na auditoria" /><Cartao titulo="Observações legadas" valor={dados.observacoes} detalhe="preservadas para consulta" /></div><div className="grade-paineis"><div className="painel"><h3>Status dos casos</h3>{dados.porStatus.map((item: any) => <div className="linha-dado" key={item.status}><span>{item.status || 'Sem status'}</span><b>{item.total}</b></div>)}</div><div className="painel"><h3>Prioridade</h3>{dados.porPrioridade.map((item: any) => <div className="linha-dado" key={item.prioridade}><span>{item.prioridade || 'Não informada'}</span><b>{item.total}</b></div>)}</div></div></section>; }

function ResumoLegadoOld({ caso, respostas }: { caso: any; respostas: Record<string, string> }) {
  const idade = Number(JSON.parse(caso.dados_json || '{}').idade || 0);
  const faixa = calcularFaixaEtaria(idade);
  const indicadores = mapearIndicadoresOperacionais(respostas);
  const dadosCaso = { ...JSON.parse(caso.dados_json || '{}'), idade, vulnerabilidade: respostas.passo4_condicao_mental === 'Sim' || respostas.passo4_limitacao_fisica === 'Sim' || respostas.passo4_depende_supervisao === 'Sim' || faixa === 'Criança', suspeitaCrime: respostas.passo4_suspeita_crime === 'Sim' || respostas.adulto_indicios_violencia === 'Sim', usoMedicacaoEssencial: respostas.passo4_medicacao === 'Sim', usoAlcoolOutrasDrogas: respostas.passo4_alcool_drogas === 'Sim', conflitoPrevio: respostas.passo4_conflito === 'Sim' };
  const alertas = avaliarAlertasArvore(respostas, faixa);
  return <aside className="resumo-legado"><p className="eyebrow">Resumo vivo</p><h3>Decisão operacional</h3><div className="linha-dado"><span>Faixa etária</span><b>{faixa}</b></div><div className="linha-dado"><span>Risco</span><b>{calcularRisco(dadosCaso, indicadores)}</b></div><div className="linha-dado"><span>Prioridade</span><b>{calcularPrioridade(dadosCaso, indicadores)}</b></div><div className="linha-dado"><span>Criticidade</span><b>{calcularCriticidadeIndicadores(indicadores)}</b></div><div className="linha-dado"><span>Apto Cabine Verde</span><b>{calcularAptoCabineVerde(dadosCaso, indicadores) ? 'Sim' : 'Não'}</b></div>{alertas.length > 0 && <div className="alertas-legado"><strong>Alertas</strong>{alertas.map(alerta => <p key={alerta}>{alerta}</p>)}</div>}</aside>;
}

const opcoesFechadas = (pergunta: any): string[] | null => { if (pergunta.id === 'p8') return ['', 'Criança (0–7)', 'Pré-adolescente (8–11)', 'Adolescente (12–17)', 'Adulto (18–59)', 'Idoso (60+)']; if (pergunta.id === 'p6') return ['', 'Feminino', 'Masculino', 'Intersexo', 'Não informado']; if (pergunta.id === 'p297') return OPCOES_SIM_NAO_NI; return pergunta.tipo === 'simNao' ? OPCOES_SIM_NAO_NI : null; };
function Question({ pergunta, valor, complemento, onChange }: { pergunta: any; valor: string; complemento: string; onChange: (valor: string, complemento: string) => void }) { const opcoes = opcoesFechadas(pergunta); return <article className="pergunta-legado"><p>{pergunta.pergunta}</p>{opcoes ? <select value={valor} onChange={e => onChange(e.target.value, complemento)}>{opcoes.map((opcao: string) => <option value={opcao} key={opcao}>{opcao || 'Selecione'}</option>)}</select> : <input value={valor} onChange={e => onChange(e.target.value, complemento)} />}{pergunta.complementoLabel && <input className="complemento" value={complemento} onChange={e => onChange(valor, e.target.value)} placeholder={pergunta.complementoLabel} />}</article>; }

const perguntasLegado = ARVORE_DECISAO_CONFIG.passos.reduce((acumulado: Record<string, any>, passo: any) => {
  passo.perguntas.forEach((pergunta: any) => { acumulado[pergunta.id] = pergunta; });
  return acumulado;
}, {});
const perguntaQuantidadeVitimas = { id: 'passo1_quantidade_vitimas', pergunta: 'Quantas pessoas desaparecidas estão sendo informadas neste caso?', tipo: 'texto' };
const perguntasIdentificacao = [...ARVORE_DECISAO_CONFIG.passos[0].perguntas.filter((pergunta: any) => ['passo1_emergencia', 'passo1_municipio', 'passo1_nome', 'passo1_sexo_genero', 'passo1_idade'].includes(pergunta.id)), perguntaQuantidadeVitimas];
const perguntasCaracteristicas = ARVORE_DECISAO_CONFIG.passos[0].perguntas.filter((pergunta: any) => !['passo1_emergencia', 'passo1_municipio', 'passo1_nome', 'passo1_sexo_genero', 'passo1_idade'].includes(pergunta.id));
const blocosPerguntasMestre = blocosMestre.map(bloco => ({ id: `bloco-${bloco.numero}`, titulo: `Bloco ${bloco.numero} · ${bloco.titulo}`, perguntas: perguntasMestre.filter(pergunta => pergunta.bloco === bloco.numero).map(pergunta => ({ ...pergunta, complementoLabel: pergunta.complemento ? 'Complemento/observação' : undefined })) }));
const fluxoCabineVerde = [blocosPerguntasMestre[0], { id: 'qualificacao-idade', titulo: 'Qualificação específica por idade', perguntas: [] }, ...blocosPerguntasMestre.slice(1)];
function extrairIdade(respostas: Record<string, any>, dados: any = {}) { const bruto = respostas.p7 ?? respostas.passo1_idade ?? dados.p7 ?? dados.idade ?? ''; const encontrado = String(bruto).match(/\d+/)?.[0] || '0'; return Number(encontrado); }

function LegacyTriageOld({ caso }: { caso: any }) {
  const [passo, setPasso] = useState(0); const [respostas, setRespostas] = useState<Record<string, string>>({}); const [complementos, setComplementos] = useState<Record<string, string>>({});
  const dadosLegado = JSON.parse(caso.dados_json || '{}'); const idade = Number(respostas.passo1_idade || dadosLegado.idade || 0); const faixa = calcularFaixaEtaria(idade); const passoAtual = fluxoCabineVerde[passo]; const subaba = ARVORE_DECISAO_CONFIG.subabas[faixa];
  const alterar = (id: string, valor: string, complemento: string) => { setRespostas(atual => ({ ...atual, [id]: valor })); setComplementos(atual => ({ ...atual, [id]: complemento })); };
  return <div className="triagem-legado"><div className="passos-legado">{ARVORE_DECISAO_CONFIG.passos.map((item: any, indice: number) => <button key={item.id} className={indice === passo ? 'ativo' : ''} onClick={() => setPasso(indice)}>{indice + 1}. {item.titulo.replace(/^PASSO \d+\s*[–-]\s*/, '')}</button>)}</div><div className="triagem-colunas"><div><div className="bloco-legado"><p className="eyebrow">PASSO {passo + 1} de {ARVORE_DECISAO_CONFIG.passos.length}</p><h3>{passoAtual.titulo}</h3>{passoAtual.perguntas.map((pergunta: any) => <Question key={pergunta.id} pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} />)}</div>{passo === ARVORE_DECISAO_CONFIG.passos.length - 1 && subaba && <div className="bloco-legado subfluxo-legado"><p className="eyebrow">Subfluxo automático · {faixa}</p><h3>{subaba.titulo}</h3>{subaba.perguntas.map((pergunta: any) => <Question key={pergunta.id} pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} />)}</div>}<div className="acoes-arvore"><button onClick={() => setPasso(Math.max(0, passo - 1))} disabled={passo === 0}>Voltar</button><span>{Object.values(respostas).filter(Boolean).length} respondidas</span><button className="primario" onClick={() => setPasso(Math.min(ARVORE_DECISAO_CONFIG.passos.length - 1, passo + 1))} disabled={passo === ARVORE_DECISAO_CONFIG.passos.length - 1}>Próximo passo</button></div></div><ResumoLegado caso={caso} respostas={respostas} /></div></div>;
}

function Trabalho() { const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); const [fotos, setFotos] = useState<any[]>([]); useEffect(() => { api.listarCasos().then(setCasos); }, []); const buscar = () => api.listarCasos(termo).then(setCasos); const selecionar = (id: string) => api.carregarCaso(id).then(c => { setCaso(c); return api.listarFotos(c.id_caso); }).then(setFotos); return <section><div className="cabecalho-secao"><div><p className="eyebrow">Operação</p><h2>Área de trabalho</h2><p>Fluxo legado preservado: cinco passos, complementos e subfluxo por faixa etária.</p></div></div><div className="trabalho"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar id, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item.idCaso)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.status || 'Sem status'}</span></button>)}</div><div className="painel arvore">{caso ? <><div className="caso-titulo"><div><h3>{caso.nome_desaparecido || caso.id_caso}</h3><p className="muted">{caso.id_caso} · {caso.talao_pm || 'Talão não informado'}</p></div><button onClick={() => api.adicionarFoto(caso.id_caso).then(() => api.listarFotos(caso.id_caso)).then(setFotos)}>Adicionar foto local</button></div><div className="fotos-local"><strong>Fotos locais: {fotos.length}</strong>{fotos.map(foto => <span key={foto.id}>{JSON.parse(foto.dados_json).nomeArquivo}</span>)}</div><LegacyTriage caso={caso} /></> : <div className="estado-vazio"><h3>Selecione um caso</h3><p>O fluxo legado de triagem aparecerá aqui.</p></div>}</div></div></section>; }

function Auditoria() { const [itens, setItens] = useState<any[]>([]); useEffect(() => { api.auditoria().then(setItens); }, []); return <section><div className="cabecalho-secao"><div><p className="eyebrow">Governança</p><h2>Auditoria e correção</h2><p>Registros incompletos e histórico preservados localmente.</p></div></div><div className="painel"><div className="tabela-cabecalho"><span>Origem</span><span>Registro</span><span>Dados</span></div>{itens.length ? itens.map(item => <div className="tabela-linha" key={item.id}><span>{item.aba}</span><span>{item.id}</span><span>{String(item.dados_json).slice(0, 180)}</span></div>) : <div className="estado-vazio"><h3>Nenhuma ocorrência carregada</h3><p>As inconsistências aparecerão aqui quando forem registradas.</p></div>}</div></section>; }
function Login({ onEntrar }: { onEntrar: (operador: Operador) => void }) {
  const [cadastro, setCadastro] = useState(false); const [email, setEmail] = useState(''); const [nome, setNome] = useState(''); const [re, setRe] = useState(''); const [postoGraduacao, setPostoGraduacao] = useState(''); const [equipe, setEquipe] = useState(''); const [mensagem, setMensagem] = useState(''); const [carregando, setCarregando] = useState(false);
  const executar = async () => { setMensagem(''); setCarregando(true); const resposta = cadastro ? await api.registrarOperador({ email, nome, re, postoGraduacao, equipe }) : await api.entrarOperador(email); setCarregando(false); if (!resposta.ok) return setMensagem(resposta.mensagem || 'Não foi possível concluir o acesso.'); localStorage.setItem('cabineVerdeOperadorNome', resposta.operador.nome); onEntrar(resposta.operador); };
  return <div className="login-local"><div className="login-card"><p className="marca">CABINE VERDE</p><h1>{cadastro ? 'Cadastro operacional' : 'Acesso operacional'}</h1><p className="muted">Uso restrito a efetivo com e-mail institucional da Polícia Militar do Estado de São Paulo.</p><label>E-mail institucional<input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="nome@policiamilitar.sp.gov.br" autoFocus /></label>{cadastro && <><label>Nome completo<input value={nome} onChange={e => setNome(e.target.value)} /></label><label>RE<input type="text" inputMode="numeric" pattern="[0-9]*" value={re} onChange={e => setRe(e.target.value.replace(/\D/g, ''))} placeholder="Somente números" /></label><label>Posto/Graduação<input value={postoGraduacao} onChange={e => setPostoGraduacao(e.target.value)} placeholder="Ex.: 1º Tenente" /></label><label>Equipe<input value={equipe} onChange={e => setEquipe(e.target.value)} placeholder="Equipe operacional" /></label></>}<button className="login-button" onClick={executar} disabled={carregando}>{carregando ? 'Validando...' : cadastro ? 'Cadastrar e entrar' : 'Entrar'}</button>{mensagem && <p className="login-erro">{mensagem}</p>}<button className="link-button" onClick={() => { setCadastro(!cadastro); setMensagem(''); }}>{cadastro ? 'Já tenho cadastro' : 'Primeiro acesso: cadastrar operador'}</button></div></div>;
}

function App() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <Dashboard /> : aba === 'trabalho' ? <Trabalho /> : <Auditoria />}</main></div>; }
createRoot(document.getElementById('root')!).render(<AppPainelPrioridadeComConfiguracoes />);

function LegacyTriage({ caso }: { caso: any }) {
  const [passo, setPasso] = useState(0); const [respostas, setRespostas] = useState<Record<string, string>>({}); const [complementos, setComplementos] = useState<Record<string, string>>({});
  const dadosLegado = JSON.parse(caso.dados_json || '{}'); const idade = Number(respostas.passo1_idade || dadosLegado.idade || 0); const faixa = calcularFaixaEtaria(idade); const passoAtual = fluxoCabineVerde[passo]; const subaba = ARVORE_DECISAO_CONFIG.subabas[faixa];
  const alterar = (id: string, valor: string, complemento: string) => { setRespostas(atual => ({ ...atual, [id]: valor })); setComplementos(atual => ({ ...atual, [id]: complemento })); };
  return <div className="triagem-legado"><div className="passos-legado">{fluxoCabineVerde.map((item, indice) => <button key={item.id} className={indice === passo ? 'ativo' : ''} onClick={() => setPasso(indice)}>{item.id.toUpperCase()} · {item.titulo}</button>)}</div><div className="triagem-colunas"><div><div className="bloco-legado"><p className="eyebrow">{passoAtual.id.toUpperCase()} · ETAPA {passo + 1} de {fluxoCabineVerde.length}</p><h3>{passoAtual.titulo}</h3>{passoAtual.perguntas.map((pergunta: any) => <Question key={pergunta.id} pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} />)}</div>{passo === fluxoCabineVerde.length - 1 && subaba && idade > 0 && <div className="bloco-legado subfluxo-legado"><p className="eyebrow">Subfluxo definido pela idade · {faixa}</p><h3>{subaba.titulo}</h3>{subaba.perguntas.map((pergunta: any) => <Question key={pergunta.id} pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} />)}</div>}<div className="acoes-arvore"><button onClick={() => setPasso(Math.max(0, passo - 1))} disabled={passo === 0}>Voltar</button><span>{Object.values(respostas).filter(Boolean).length} respondidas</span><button className="primario" onClick={() => setPasso(Math.min(fluxoCabineVerde.length - 1, passo + 1))} disabled={passo === fluxoCabineVerde.length - 1}>Próximo passo</button></div></div><ResumoLegado caso={caso} respostas={respostas} /></div></div>;
}

function FotoFinal({ caso, operador = 'sessao-local' }: { caso: any; operador?: string }) {
  const [fotos, setFotos] = useState<any[]>([]); const [autorizacao, setAutorizacao] = useState(''); const [mensagem, setMensagem] = useState('');
  const atualizar = () => api.listarFotos(caso.id_caso).then(setFotos);
  useEffect(() => { atualizar(); }, [caso.id_caso]);
  const fotoPendente = fotos.find(foto => { if (foto.autorizacao === 'Pendente') return true; try { return JSON.parse(foto.dados_json || '{}').autorizacaoUsoImagem === 'Pendente'; } catch { return false; } });
  const anexar = async () => {
    let registroAtual: any = caso;
    try { registroAtual = await api.carregarCaso(caso.id_caso) || caso; } catch { registroAtual = caso; }
    let dadosAtual: any = {};
    try { dadosAtual = JSON.parse(registroAtual.dados_json || '{}'); } catch {}
    const respostasAtual = dadosAtual.respostasArvore || registroAtual.respostasArvore || {};
    const pendentes = obterRespostasPendentes();
    const nome = String(registroAtual.nome_desaparecido || dadosAtual.nome_desaparecido || respostasAtual.__nomeCaso || respostasAtual.passo1_nome || respostasAtual.nomeCompletoDesaparecido || pendentes.passo1_nome || pendentes.nomeCompletoDesaparecido || '').trim();
    const dataTalao = String(registroAtual.data_talao || dadosAtual.data_talao || respostasAtual.__dataTalao || caso.data_talao || '').trim();
    const talao = String(registroAtual.talao_pm || dadosAtual.talao_pm || respostasAtual.__talaoPMESP || caso.talao_pm || '').trim();
    const faltantes = [['nome completo', nome], ['data do talão', dataTalao], ['número do talão', talao]].filter(([, valor]) => !valor).map(([rotulo]) => rotulo);
    if (faltantes.length) { setMensagem(`Preencha antes de inserir a foto: ${faltantes.join(', ')}.`); return; }
    const resultado = await api.adicionarFoto(caso.id_caso, { nome, dataTalao, talao, operador });
    if (!resultado || resultado.ok === false) { setMensagem(resultado?.mensagem || 'Não foi possível salvar a foto vinculada ao caso.'); return; }
    const atualizacaoStatus = await api.corrigirCaso({ idCaso: caso.id_caso, campos: { statusAtendimento: 'Em triagem', status: 'Em triagem' }, justificativa: 'Inserção de imagem da vítima', operador });
    setMensagem(atualizacaoStatus.ok ? `Imagem salva e vinculada a ${resultado.nome || nome} · status atualizado para Em triagem.` : `Imagem salva e vinculada a ${resultado.nome || nome}, mas o status não pôde ser atualizado.`); setAutorizacao(''); await atualizar();
  };
  const registrar = () => { if (!fotoPendente) return setMensagem('Insira uma imagem antes de registrar a autorização.'); api.registrarConsentimentoFoto({ idFoto: fotoPendente.id, url: fotoPendente.url, autorizacao }).then(resultado => { setMensagem(resultado.ok ? 'Autorização registrada com a imagem.' : resultado.mensagem); setAutorizacao(''); atualizar(); }); };
  return <div className="foto-final bloco-legado"><p className="eyebrow">Etapa final · imagem da pessoa desaparecida</p><h3>Foto para apoio às buscas</h3><p className="muted">A imagem é armazenada na pasta local do caso ou no servidor central, conforme a configuração deste computador.</p><button className="primario" onClick={anexar}>Inserir foto da vítima</button>{fotos.length > 0 && <div className="fotos-local">{fotos.map(foto => { let dados: any = {}; try { dados = JSON.parse(foto.dados_json || '{}'); } catch {} return <span key={foto.id}>{foto.nomeArquivo || dados.nomeArquivo || 'Imagem'} · autorização: {foto.autorizacao || dados.autorizacaoUsoImagem || 'Pendente'}</span>; })}</div>}{fotoPendente && <div className="autorizacao-foto"><p>O responsável autoriza o uso desta imagem exclusivamente para fins de busca, identificação e divulgação operacional interna pela Polícia Militar do Estado de São Paulo?</p><select value={autorizacao} onChange={e => setAutorizacao(e.target.value)}><option value="">Selecione</option><option value="Sim">Sim, autorizo</option><option value="Não">Não autorizo</option><option value="Não informado">Não informado</option></select><button onClick={registrar} disabled={!autorizacao}>Registrar autorização</button></div>}{mensagem && <p className="muted">{mensagem}</p>}</div>;
}

function ResumoLegado({ caso, respostas }: { caso: any; respostas: Record<string, string> }) {
  const dados = JSON.parse(caso.dados_json || '{}'); const idade = Number(respostas.passo1_idade || dados.idade || 0); const faixa = calcularFaixaEtaria(idade); const indicadores = mapearIndicadoresOperacionais(respostas); const dadosCaso = { ...dados, idade, vulnerabilidade: respostas.passo4_condicao_mental === 'Sim' || respostas.passo4_limitacao_fisica === 'Sim' || respostas.passo4_depende_supervisao === 'Sim' || faixa === 'Criança', suspeitaCrime: respostas.passo4_suspeita_crime === 'Sim', usoMedicacaoEssencial: respostas.passo4_medicacao === 'Sim', conflitoPrevio: respostas.passo4_conflito === 'Sim' };
  return <aside className="resumo-legado"><p className="eyebrow">Resumo vivo</p><h3>Decisão operacional</h3><div className="linha-dado"><span>Faixa etária</span><b>{faixa}</b></div><div className="linha-dado"><span>Risco</span><b>{calcularRisco(dadosCaso, indicadores)}</b></div><div className="linha-dado"><span>Prioridade</span><b>{calcularPrioridade(dadosCaso, indicadores)}</b></div><div className="linha-dado"><span>Apto Cabine Verde</span><b>{calcularAptoCabineVerde(dadosCaso, indicadores) ? 'Sim' : 'Não'}</b></div><FotoFinal caso={caso} /></aside>;
}

function AuditoriaCorrigida() {
  const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); const [campos, setCampos] = useState<Record<string, string>>({}); const [justificativa, setJustificativa] = useState(''); const [historico, setHistorico] = useState<any[]>([]); const [mensagem, setMensagem] = useState('');
  const buscar = () => api.listarAuditoriaCasos(termo).then(setCasos);
  useEffect(() => { buscar(); }, []);
  const selecionar = (item: any) => { api.carregarCaso(item.idCaso).then(registro => { const dados = JSON.parse(registro.dados_json || '{}'); setCaso(registro); setCampos({ nome_desaparecido: registro.nome_desaparecido || '', talao_pm: registro.talao_pm || '', status_caso: registro.status_caso || '', municipio: dados.municipio || '', idade: dados.idade ? String(dados.idade) : '', sexoGenero: dados.sexoGenero || '', dataHoraUltimaVisualizacao: dados.dataHoraUltimaVisualizacao || '', localUltimaVisualizacao: dados.localUltimaVisualizacao || '', observacoesOperacionais: dados.observacoesOperacionais || '', numeroBo: dados.numeroBo || '', prioridade: dados.prioridade || '', classificacaoRisco: dados.classificacaoRisco || '' }); return api.historicoCaso(item.idCaso); }).then(setHistorico); setMensagem(''); };
  const alterar = (campo: string, valor: string) => setCampos(atual => ({ ...atual, [campo]: valor }));
  const salvar = () => { if (!caso) return; api.corrigirCaso({ idCaso: caso.id_caso, campos, justificativa, operador: 'sessao-local' }).then(resultado => { setMensagem(resultado.ok ? 'Correção registrada e auditada.' : resultado.mensagem); if (resultado.ok) { setJustificativa(''); selecionar({ idCaso: caso.id_caso }); buscar(); api.dashboard(); } }); };
  return <section><div className="cabecalho-secao"><div><p className="eyebrow">Governança</p><h2>Auditoria e correção</h2><p>Revise dados incompletos, corrija informações e registre a justificativa de cada alteração.</p></div></div><div className="trabalho auditoria-local"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar caso, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.statusMigracao || item.status}</span></button>)}</div><div className="painel auditoria-editor">{caso ? <><div className="caso-titulo"><div><p className="eyebrow">Correção controlada</p><h3>{caso.id_caso}</h3></div></div><div className="form-correcoes">{[['nome_desaparecido', 'Nome da pessoa desaparecida'], ['talao_pm', 'Talão PMESP'], ['status_caso', 'Status do caso'], ['municipio', 'Município'], ['idade', 'Idade'], ['sexoGenero', 'Sexo/Gênero'], ['dataHoraUltimaVisualizacao', 'Data/hora da última visualização'], ['localUltimaVisualizacao', 'Local da última visualização'], ['numeroBo', 'Número do BO'], ['prioridade', 'Prioridade'], ['classificacaoRisco', 'Classificação de risco']].map(([campo, rotulo]) => <label key={campo}>{rotulo}<input value={campos[campo] || ''} onChange={e => alterar(campo, e.target.value)} /></label>)}<label>Observações operacionais<textarea value={campos.observacoesOperacionais || ''} onChange={e => alterar('observacoesOperacionais', e.target.value)} /></label><label>Justificativa obrigatória da correção<textarea value={justificativa} onChange={e => setJustificativa(e.target.value)} placeholder="Descreva a fonte ou o motivo da alteração" /></label><button className="primario" onClick={salvar} disabled={!justificativa.trim()}>Salvar correção auditada</button>{mensagem && <p className="muted">{mensagem}</p>}</div><div className="historico-correcoes"><h3>Histórico de alterações</h3>{historico.length ? historico.map(item => <div className="linha-dado" key={item.id}><span>{item.criado_em}<br />{item.justificativa}</span><b>{Object.keys(JSON.parse(item.alteracoes_json || '{}')).length} campo(s)</b></div>) : <p className="muted">Nenhuma correção registrada para este caso.</p>}</div></> : <div className="estado-vazio"><h3>Selecione um caso</h3><p>A fila mostra casos incompletos e permite localizar qualquer registro para correção.</p></div>}</div></div></section>;
}

function AppFluxoCorrigido() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <Dashboard /> : aba === 'trabalho' ? <TrabalhoFluxo /> : <AuditoriaCorrigida />}</main></div>; }

function DashboardIndices() { const [dados, setDados] = useState<any>(); useEffect(() => { api.dashboard().then(setDados); }, []); if (!dados) return <p className="carregando">Carregando indicadores locais...</p>; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Visão operacional</p><h2>Dashboard</h2><p>Indicadores consolidados dos atendimentos no banco local.</p></div></div><div className="grade-cartoes indicadores-principais"><Cartao titulo="Casos" valor={dados.totalCasos} detalhe="casos registrados" /><Cartao titulo="Pessoas localizadas" valor={dados.pessoasLocalizadas} detalhe="localizações registradas" /><Cartao titulo="Atuação exclusiva Cabine Verde" valor={dados.atuacaoExclusivaCabineVerde} detalhe="casos aptos ao fluxo exclusivo" /></div><div className="grade-paineis"><div className="painel"><h3>Status dos casos</h3>{dados.porStatus.map((item: any) => <div className="linha-dado" key={item.status}><span>{item.status || 'Sem status'}</span><b>{item.total}</b></div>)}</div><div className="painel"><h3>Prioridade</h3>{dados.porPrioridade.map((item: any) => <div className="linha-dado" key={item.prioridade}><span>{item.prioridade || 'Não informada'}</span><b>{item.total}</b></div>)}</div></div></section>; }

function AppIndices() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardIndices /> : aba === 'trabalho' ? <TrabalhoFluxo /> : <AuditoriaCorrigida />}</main></div>; }

function AuditoriaCompleta() {
  const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); const [campos, setCampos] = useState<Record<string, string>>({}); const [justificativa, setJustificativa] = useState(''); const [mensagem, setMensagem] = useState('');
  const buscar = () => api.listarAuditoriaCasos(termo).then(setCasos); useEffect(() => { buscar(); }, []);
  const selecionar = (item: any) => api.carregarCaso(item.idCaso).then(registro => { const dados = JSON.parse(registro.dados_json || '{}'); setCaso(registro); setCampos({ nome_desaparecido: registro.nome_desaparecido || '', resultadoLocalizacao: dados.resultadoLocalizacao || '', recursoLocalizacao: dados.recursoLocalizacao || '', atuacaoExclusivaCabineVerde: dados.atuacaoExclusivaCabineVerde || '', dataHoraLocalizacao: dados.dataHoraLocalizacao || '', observacoesLocalizacao: dados.observacoesLocalizacao || '' }); });
  const alterar = (campo: string, valor: string) => setCampos(atual => ({ ...atual, [campo]: valor }));
  const salvar = () => { if (!caso) return; api.corrigirCaso({ idCaso: caso.id_caso, campos, justificativa, operador: 'sessao-local' }).then(resultado => { setMensagem(resultado.ok ? 'Localização/correção registrada com auditoria.' : resultado.mensagem); if (resultado.ok) { setJustificativa(''); selecionar({ idCaso: caso.id_caso }); buscar(); api.dashboard(); } }); };
  return <section><div className="cabecalho-secao"><div><p className="eyebrow">Governança</p><h2>Auditoria e correção</h2><p>Registre a localização, o resultado e o recurso utilizado sem perder o histórico da alteração.</p></div></div><div className="trabalho auditoria-local"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar caso, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.statusMigracao || item.status}</span></button>)}</div><div className="painel auditoria-editor">{caso ? <><p className="eyebrow">Registro de desfecho</p><h3>{caso.id_caso} · {caso.nome_desaparecido || 'Sem nome'}</h3><div className="form-correcoes"><label>Nome da pessoa<input value={campos.nome_desaparecido || ''} onChange={e => alterar('nome_desaparecido', e.target.value)} /></label><label>Resultado da localização<select value={campos.resultadoLocalizacao || ''} onChange={e => alterar('resultadoLocalizacao', e.target.value)}><option value="">Não informado</option><option value="Não localizado">Ainda não localizada</option><option value="Localizado vivo">Localizado vivo</option><option value="Localizado morto">Localizado morto</option><option value="Localizado preso">Localizado preso</option></select></label><label>Recurso responsável pela localização<select value={campos.recursoLocalizacao || ''} onChange={e => alterar('recursoLocalizacao', e.target.value)}><option value="">Não informado</option><option value="Viatura">Viatura</option><option value="Familiares">Familiares</option><option value="Cabine Verde">Atuação exclusiva da Cabine Verde</option><option value="Polícia Civil">Polícia Civil</option><option value="Outros">Outros</option></select></label><label>Atuação exclusiva da Cabine Verde<select value={campos.atuacaoExclusivaCabineVerde || ''} onChange={e => alterar('atuacaoExclusivaCabineVerde', e.target.value)}><option value="">Não informado</option><option value="Sim">Sim</option><option value="Não">Não</option></select></label><label>Data e hora da localização<input type="datetime-local" value={campos.dataHoraLocalizacao || ''} onChange={e => alterar('dataHoraLocalizacao', e.target.value)} /></label><label className="campo-largo">Observações da localização<textarea value={campos.observacoesLocalizacao || ''} onChange={e => alterar('observacoesLocalizacao', e.target.value)} placeholder="Descreva como a pessoa foi localizada e quem participou." /></label><label className="campo-largo">Justificativa obrigatória<textarea value={justificativa} onChange={e => setJustificativa(e.target.value)} placeholder="Informe a fonte da informação ou motivo da correção." /></label><button className="primario" onClick={salvar} disabled={!justificativa.trim()}>Salvar desfecho auditado</button>{mensagem && <p className="muted">{mensagem}</p>}</div></> : <div className="estado-vazio"><h3>Selecione um caso</h3><p>Aqui será registrado se a pessoa foi localizada viva, morta ou presa, além do recurso utilizado.</p></div>}</div></div></section>;
}

function AppFinal() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardIndices /> : aba === 'trabalho' ? <TrabalhoFluxo /> : <AuditoriaCompleta />}</main></div>; }

function DesfechoOperacional({ caso }: { caso: any }) {
  const dados = JSON.parse(caso.dados_json || '{}'); const [nome, setNome] = useState(caso.nome_desaparecido || ''); const [campos, setCampos] = useState({ resultadoLocalizacao: dados.resultadoLocalizacao || '', recursoLocalizacao: dados.recursoLocalizacao || '', atuacaoExclusivaCabineVerde: dados.atuacaoExclusivaCabineVerde || '', dataHoraLocalizacao: dados.dataHoraLocalizacao || '', observacoesLocalizacao: dados.observacoesLocalizacao || '' }); const [mensagem, setMensagem] = useState(''); const alterar = (campo: string, valor: string) => setCampos(atual => ({ ...atual, [campo]: valor })); const salvar = () => api.salvarDesfechoOperacional({ idCaso: caso.id_caso, nome, campos, operador: 'sessao-local' }).then(resposta => setMensagem(resposta.ok ? 'Desfecho salvo e disponível para os indicadores.' : resposta.mensagem));
  return <div className="bloco-legado desfecho-operacional"><p className="eyebrow">Registro obrigatório para extração de indicadores</p><h3>Desfecho da localização</h3><label>Nome da pessoa<input value={nome} onChange={e => setNome(e.target.value)} placeholder="Nome completo" /></label><label>Resultado<select value={campos.resultadoLocalizacao} onChange={e => alterar('resultadoLocalizacao', e.target.value)}><option value="">Não informado</option><option value="Não localizado">Não localizado</option><option value="Localizado vivo">Localizado vivo</option><option value="Localizado morto">Localizado morto</option><option value="Localizado preso">Localizado preso</option></select></label><label>Recurso utilizado<select value={campos.recursoLocalizacao} onChange={e => alterar('recursoLocalizacao', e.target.value)}><option value="">Não informado</option><option value="Viatura">Viatura</option><option value="Familiares">Familiares</option><option value="Cabine Verde">Cabine Verde</option><option value="Polícia Civil">Polícia Civil</option><option value="Outros">Outros</option></select></label><label>Atuação exclusiva da Cabine Verde<select value={campos.atuacaoExclusivaCabineVerde} onChange={e => alterar('atuacaoExclusivaCabineVerde', e.target.value)}><option value="">Não informado</option><option value="Sim">Sim</option><option value="Não">Não</option></select></label><label>Data e hora<input type="datetime-local" value={campos.dataHoraLocalizacao} onChange={e => alterar('dataHoraLocalizacao', e.target.value)} /></label><label>Observações<textarea value={campos.observacoesLocalizacao} onChange={e => alterar('observacoesLocalizacao', e.target.value)} placeholder="Como a pessoa foi localizada e quem participou." /></label><button className="primario" onClick={salvar}>Salvar desfecho do caso</button>{mensagem && <p className="muted">{mensagem}</p>}</div>;
}

function TrabalhoComDesfecho() { const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); useEffect(() => { api.listarCasos().then(setCasos); }, []); const buscar = () => api.listarCasos(termo).then(setCasos); const novoCaso = () => setCaso({ id_caso: 'NOVO-' + Date.now(), nome_desaparecido: '', dados_json: '{}' }); const selecionar = (id: string) => api.carregarCaso(id).then(setCaso); return <section><div className="cabecalho-secao"><div><p className="eyebrow">Operação</p><h2>Área de trabalho</h2><p>Preencha a árvore de decisão e registre o desfecho para alimentar os indicadores.</p></div><button className="primario" onClick={novoCaso}>＋ Novo caso</button></div><div className="trabalho"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar caso, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item.idCaso)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.status || 'Sem status'}</span></button>)}</div><div className="painel arvore">{caso ? <><LegacyTriage caso={caso} /><DesfechoOperacional caso={caso} /></> : <div className="estado-vazio"><h3>Comece um atendimento</h3><p>Use “Novo caso”, siga a árvore e depois registre o resultado da localização.</p></div>}</div></div></section>; }

function AppOperacao() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardIndices /> : aba === 'trabalho' ? <TrabalhoComDesfecho /> : <AuditoriaCompleta />}</main></div>; }

function AuditoriaFinal() {
  const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); const [campos, setCampos] = useState<Record<string, string>>({}); const [justificativa, setJustificativa] = useState(''); const [mensagem, setMensagem] = useState(''); const sequenciaBusca = useRef(0); const buscar = () => { const sequencia = ++sequenciaBusca.current; api.listarAuditoriaCasos(termo).then(resultado => { if (sequencia !== sequenciaBusca.current) return; const unicos = new Map<string, any>(); for (const item of resultado) { const chave = String(item.idCaso || item.id_caso || item.talaoPMESP || item.talao_pm || ''); const anterior = unicos.get(chave); if (!anterior || String(item.statusMigracao || '').toUpperCase() === 'CORRIGIDO' || String(item.status || '').toUpperCase().includes('LOCALIZADO')) unicos.set(chave, item); } setCasos([...unicos.values()]); }); }; useEffect(() => { buscar(); }, []); const alterar = (campo: string, valor: string) => setCampos(atual => ({ ...atual, [campo]: valor }));
  const selecionar = (item: any) => api.carregarCaso(item.idCaso).then(registro => { const dados = JSON.parse(registro.dados_json || '{}'); setCaso(registro); setCampos({ nome_desaparecido: registro.nome_desaparecido || '', statusVitima: dados.statusVitima || '', condicaoVitima: dados.condicaoVitima || '', desfechoCaso: dados.desfechoCaso || '', encaminhamento: dados.encaminhamento || '', recursoLocalizacao: dados.recursoLocalizacao || '', atuacaoExclusivaCabineVerde: dados.atuacaoExclusivaCabineVerde || '', vultoImprensa: dados.vultoImprensa || dados.teveMidia || '', observacoesLocalizacao: dados.observacoesLocalizacao || '' }); });
  const salvar = () => { if (!caso || !justificativa.trim()) return; const camposFinalizacao = { ...campos, categoriaAdministrativa: derivarCategoriaAdministrativa(campos) }; api.corrigirCaso({ idCaso: caso.id_caso, campos: camposFinalizacao, justificativa, operador: 'sessao-local' }).then(resposta => { setMensagem(resposta.ok ? 'Status e desfecho atualizados com auditoria.' : resposta.mensagem); if (resposta.ok) { setJustificativa(''); selecionar({ idCaso: caso.id_caso }); buscar(); api.dashboard(); } }); };
  return <section><div className="cabecalho-secao"><div><p className="eyebrow">Encerramento operacional</p><h2>Finalização e desfecho</h2><p>Atualize o status da vítima, condição, desfecho, encaminhamento, vulto/imprensa e recursos utilizados.</p></div></div><div className="trabalho auditoria-local"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar caso, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.statusMigracao || item.status}</span></button>)}</div><div className="painel auditoria-editor">{caso ? <><p className="eyebrow">Atualização controlada do caso</p><h3>{caso.id_caso} · {caso.nome_desaparecido || 'Sem nome'}</h3><div className="form-correcoes"><label>Nome da vítima<input value={campos.nome_desaparecido || ''} onChange={e => alterar('nome_desaparecido', e.target.value)} /></label><label>Status da vítima<select value={campos.statusVitima || ''} onChange={e => alterar('statusVitima', e.target.value)}><option value="">Não informado</option><option>Desaparecida</option><option>Não localizada</option><option>Localizada</option><option>Localizada viva</option><option>Localizada morta</option><option>Localizada presa</option></select></label><label>Condição da vítima<select value={campos.condicaoVitima || ''} onChange={e => alterar('condicaoVitima', e.target.value)}><option value="">Não informado</option><option>Em segurança</option><option>Vulnerável</option><option>Ferida</option><option>Hospitalizada</option><option>Em óbito</option><option>Custodiada</option><option>Outra condição</option></select></label><label>Desfecho<select value={campos.desfechoCaso || ''} onChange={e => alterar('desfechoCaso', e.target.value)}><option value="">Não informado</option><option>Em acompanhamento</option><option>Encerrado - localizada</option><option>Encerrado - óbito</option><option>Encerrado - presa</option><option>Sem localização</option></select></label><label>Encaminhamento<select value={campos.encaminhamento || ''} onChange={e => alterar('encaminhamento', e.target.value)}><option value="">Não informado</option><option>Família/responsável</option><option>Hospital/serviço de saúde</option><option>Delegacia</option><option>Conselho Tutelar</option><option>Sistema prisional</option><option>Outro órgão</option></select></label><label>Recurso principal<select value={campos.recursoLocalizacao || ''} onChange={e => alterar('recursoLocalizacao', e.target.value)}><option value="">Não informado</option><option>Viatura</option><option>Familiares</option><option>Outros órgãos</option><option>Videomonitoramento</option><option>Reconhecimento facial</option><option>Cabine Verde</option><option>Outros</option></select></label><label>Atuação exclusiva da Cabine Verde<select value={campos.atuacaoExclusivaCabineVerde || ''} onChange={e => alterar('atuacaoExclusivaCabineVerde', e.target.value)}><option value="">Não informado</option><option>Sim</option><option>Não</option></select></label><label>Vulto/imprensa?<select value={campos.vultoImprensa || ''} onChange={e => alterar('vultoImprensa', e.target.value)}><option value="">Não informado</option><option value="Sim">Sim</option><option value="Não">Não</option></select></label><label className="campo-largo">Observações do desfecho<textarea value={campos.observacoesLocalizacao || ''} onChange={e => alterar('observacoesLocalizacao', e.target.value)} placeholder="Descreva as providências e informações confirmadas." /></label><label className="campo-largo">Justificativa obrigatória<textarea value={justificativa} onChange={e => setJustificativa(e.target.value)} placeholder="Informe a fonte ou motivo da atualização." /></label><button className="primario" onClick={salvar} disabled={!justificativa.trim()}>Salvar atualização auditada</button>{mensagem && <p className="muted">{mensagem}</p>}</div></> : <div className="estado-vazio"><h3>Selecione um caso</h3><p>O editor permite atualizar o ciclo completo do atendimento.</p></div>}</div></div></section>;
}

function AppAuditoriaFinal() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardIndices /> : aba === 'trabalho' ? <TrabalhoComDesfecho /> : <AuditoriaFinal />}</main></div>; }

const mapaLegadoPerguntas: Record<string, string> = { passo1_municipio: 'municipio', passo1_nome: 'nomeCompletoDesaparecido', passo1_sexo_genero: 'sexoGenero', passo1_idade: 'idade', passo1_foto_digital: 'fotoDisponivel', passo1_dispositivo: 'dispositivoLigado', passo2_data_hora: 'dataHoraUltimaVisualizacao', passo2_local: 'localUltimaVisualizacao', passo2_roupa: 'roupaUltimaVisualizacao', passo2_transporte: 'meioTransporte', passo2_caracteristicas_transporte: 'dadosVeiculo', passo3_vinculo: 'vinculoSolicitante', passo4_condicao_mental: 'condicaoMentalCognitivaComportamental', passo4_limitacao_fisica: 'limitacaoFisica', passo4_medicacao: 'usoMedicacaoEssencial', passo4_alcool_drogas: 'usoAlcoolOutrasDrogas', passo4_desapareceu_antes: 'historicoDesaparecimentoAnterior', passo4_conflito: 'conflitoPrevio', passo4_suspeita_crime: 'suspeitaCrime', passo5_aparelho_ligado: 'dispositivoLigado', passo5_cameras_residencia: 'camerasResidencia', passo5_cameras_ultimo_local: 'camerasUltimoLocal', passo5_registro_delegacia: 'numeroBo' };
const mapaRespostasUnificadas: Record<string, string[]> = {
  p1: ['emergencia'], p2: ['municipio', 'passo1_municipio'], p3: ['nome_desaparecido', 'nomeCompletoDesaparecido', 'nome', 'passo1_nome'], p6: ['sexoGenero', 'passo1_sexo_genero'], p7: ['idade', 'passo1_idade'],
  p9: ['cpf'], p10: ['rg'], p11: ['dataNascimento'], p15: ['endereco'], p16: ['telefoneDesaparecido', 'telefone'], p17: ['fotoDisponivel', 'passo1_foto_digital'],
  p19: ['dispositivoLigado'], p20: ['dispositivoLigado'], p21: ['telefoneDesaparecido', 'telefone'], p26: ['dataUltimaVisualizacao'],
  p27: ['horaUltimaVisualizacao'], p28: ['localUltimaVisualizacao', 'passo2_local'], p30: ['sentidoTomado', 'destinoProvavel'], p38: ['roupaUltimaVisualizacao', 'passo2_roupa'], p40: ['meioTransporte', 'passo2_transporte'],
  p45: ['dadosVeiculo', 'passo2_caracteristicas_transporte'], p70: ['caracteristicasBasicas', 'caracteristicasMarcantes'], p107: ['usoMedicacaoEssencial'], p109: ['riscoInterrupcaoMedicacao'], p110: ['dependeCuidador'],
  p117: ['riscoSuicidio'], p120: ['doencaGrave'], p288: ['riscoVida'], p289: ['riscoSuicidio'], p290: ['riscoMedico'], p291: ['suspeitaCrime']
};
const mapaCamposF2Unificados: Record<string, string[]> = {
  idade: ['p7'], municipio: ['p2'], nome: ['p3'], cpf: ['p9'], rg: ['p10'], dataNascimento: ['p11'], telefone: ['p16'],
  endereco: ['p15'], sentidoTomado: ['p30'], caracteristicasBasicas: ['p70'], nomeSolicitante: ['nomeSolicitante'],
  telefoneSolicitante: ['telefoneSolicitante'], historicoF2: ['historicoF2'], observacoes: ['observacoesOperacionais']
};
const CHAVE_RESPOSTAS_PENDENTES = 'cabine-verde-respostas-unificadas';
const obterRespostasPendentes = (): Record<string, string> => {
  try { return JSON.parse(localStorage.getItem(CHAVE_RESPOSTAS_PENDENTES) || '{}'); } catch { return {}; }
};
const obterRespostasUnificadas = (caso: any): Record<string, string> => {
  const origem = caso && typeof caso === 'object' ? caso : {};
  const dados = JSON.parse(origem.dados_json || '{}');
  return { ...dados, ...origem, ...(dados.respostasArvore || {}), ...(origem.respostasArvore || {}), ...obterRespostasPendentes() };
};
const registrarRespostaUnificada = (id: string, valor: string, complemento = ''): void => {
  const atual = obterRespostasPendentes();
  const chaves = [id, ...(mapaRespostasUnificadas[id] || [])];
  chaves.forEach(chave => { if (valor !== '') atual[chave] = valor; });
  if (complemento !== '') atual[`${id}_complemento`] = complemento;
  localStorage.setItem(CHAVE_RESPOSTAS_PENDENTES, JSON.stringify(atual));
};
const registrarDadosF2Unificados = (dados: Record<string, string>): void => {
  Object.entries(dados).forEach(([campo, valor]) => {
    if (!valor) return;
    const ids = mapaCamposF2Unificados[campo] || [Object.entries(mapaRespostasUnificadas).find(([, aliases]) => aliases.includes(campo))?.[0] || campo];
    ids.forEach(id => registrarRespostaUnificada(id, String(valor)));
  });
};
function valorAutoPreenchido(pergunta: any, dados: any): string { const unificados = obterRespostasUnificadas(dados); const valor = unificados[pergunta.id] ?? unificados[mapaLegadoPerguntas[pergunta.id]] ?? mapaRespostasUnificadas[pergunta.id]?.map(chave => unificados[chave]).find(Boolean); if (valor === undefined || valor === null || valor === '') return ''; if (pergunta.tipo === 'simNao') { if (['sim', 'true', '1', 'yes'].includes(String(valor).toLowerCase())) return 'Sim'; if (['não', 'nao', 'false', '0', 'no'].includes(String(valor).toLowerCase())) return 'Não'; } return String(valor); }
function FluxoSequencial({ caso }: { caso: any }) { const dados = JSON.parse(caso.dados_json || '{}'); const respostasIniciais = Object.fromEntries([...fluxoCabineVerde.flatMap(item => item.perguntas), ...Object.values(ARVORE_DECISAO_CONFIG.subabas).flatMap((item: any) => item.perguntas)].map((pergunta: any) => [pergunta.id, valorAutoPreenchido(pergunta, dados)]).filter(([, valor]) => valor)); const [respostas, setRespostas] = useState<Record<string, string>>(respostasIniciais); const [complementos, setComplementos] = useState<Record<string, string>>({}); const idade = Number(respostas.passo1_idade || 0); const faixa = calcularFaixaEtaria(idade); const subaba = ARVORE_DECISAO_CONFIG.subabas[faixa]; const sequencia = [...fluxoCabineVerde.flatMap(item => item.perguntas.map((pergunta: any) => ({ ...pergunta, bloco: item }))), ...(idade > 0 && subaba ? subaba.perguntas.map((pergunta: any) => ({ ...pergunta, bloco: { id: 'subfluxo', titulo: subaba.titulo } })) : [])]; const [indice, setIndice] = useState(0); const atual = sequencia[Math.min(indice, Math.max(0, sequencia.length - 1))]; const valor = atual ? respostas[atual.id] || '' : ''; const alterar = (novoValor: string, complemento: string) => { setRespostas(anterior => ({ ...anterior, [atual.id]: novoValor })); setComplementos(anterior => ({ ...anterior, [atual.id]: complemento })); }; if (!atual) return <div className="fluxo-sequencial concluido"><p className="eyebrow">Fluxo concluído</p><h3>Árvore preenchida</h3><p>Revise o desfecho abaixo e salve o resultado operacional.</p></div>; return <div className="fluxo-sequencial"><div className="progresso-fluxo"><span>{atual.bloco.id === 'subfluxo' ? 'SUBFLUXO' : atual.bloco.id.toUpperCase()}</span><b>Pergunta {indice + 1} de {sequencia.length}</b><small>{Object.values(respostas).filter(Boolean).length} respostas preenchidas</small></div><div className="pergunta-foco"><p className="eyebrow">{atual.bloco.titulo}</p><h3>{atual.pergunta}</h3>{mapaLegadoPerguntas[atual.id] && valorAutoPreenchido(atual, dados) && <span className="selo-legado">Preenchida automaticamente do legado</span>}<Question pergunta={atual} valor={valor} complemento={complementos[atual.id] || ''} onChange={alterar} /></div><div className="acoes-arvore"><button onClick={() => setIndice(Math.max(0, indice - 1))} disabled={indice === 0}>Voltar</button><button className="primario" onClick={() => setIndice(Math.min(sequencia.length, indice + 1))}>{indice === sequencia.length - 1 ? 'Concluir perguntas' : 'Próxima pergunta'}</button></div></div>; }

function TrabalhoSequencial() { const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); useEffect(() => { api.listarCasos().then(setCasos); }, []); const buscar = () => api.listarCasos(termo).then(setCasos); const selecionar = (id: string) => api.carregarCaso(id).then(setCaso); const novoCaso = () => setCaso({ id_caso: 'NOVO-' + Date.now(), nome_desaparecido: '', dados_json: '{}' }); return <section><div className="cabecalho-secao"><div><p className="eyebrow">Operação</p><h2>Área de trabalho</h2><p>Uma pergunta por vez, com preenchimento automático dos dados legados.</p></div><button className="primario" onClick={novoCaso}>＋ Novo caso</button></div><div className="trabalho"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar caso, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item.idCaso)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.status || 'Sem status'}</span></button>)}</div><div className="painel arvore">{caso ? <><FluxoSequencial key={caso.id_caso} caso={caso} /><DesfechoOperacional caso={caso} /></> : <div className="estado-vazio"><h3>Comece um atendimento</h3><p>Clique em “Novo caso” para iniciar o fluxo sequencial.</p></div>}</div></div></section>; }

function AppSequencial() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardIndices /> : aba === 'trabalho' ? <TrabalhoSequencial /> : <AuditoriaFinal />}</main></div>; }

function BuscaImagens() { const [termo, setTermo] = useState(''); const [resultados, setResultados] = useState<any[]>([]); const buscar = () => api.buscarFotos(termo).then(setResultados); return <section><div className="cabecalho-secao"><div><p className="eyebrow">Consulta operacional</p><h2>Buscar imagem</h2><p>Localize fotos por nome, talão ou cadastro.</p></div></div><div className="painel busca-imagens"><div className="busca"><input autoFocus value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Nome, talão ou cadastro" /><button className="primario" onClick={buscar}>Buscar imagem</button></div>{resultados.length ? resultados.map(item => <div className="resultado-imagem" key={item.id}><div><strong>{item.nome}</strong><span>{item.idCaso} · Talão {item.talao} · {item.nomeArquivo}</span><small>Autorização: {item.autorizacao}</small></div><button onClick={() => api.abrirFoto(item.caminhoLocal)}>Abrir imagem</button></div>) : <p className="muted">Digite um nome, talão ou cadastro para localizar imagens.</p>}</div></section>; }

function ConfrontoImagem() { const [imagem, setImagem] = useState<any>(); const [candidatos, setCandidatos] = useState<any[]>([]); const [mensagem, setMensagem] = useState(''); const [limiar, setLimiar] = useState(60); const [arrastando, setArrastando] = useState(false); const selecionar = () => { setMensagem(''); setCandidatos([]); api.selecionarImagemConfronto().then(setImagem); }; const carregarArquivo = (arquivo?: File) => { const extensaoImagem = /\.(jpe?g|png|webp|gif)$/i.test(arquivo?.name || ''); const tipoImagem = Boolean(arquivo?.type?.startsWith('image/')); const caminho = arquivo ? String(api.obterCaminhoArquivoArrastado(arquivo) || (arquivo as any).path || '') : ''; if (!arquivo || (!tipoImagem && !extensaoImagem) || !caminho) { setMensagem('Não foi possível anexar. Solte um arquivo JPG, PNG ou WEBP diretamente nesta janela.'); return; } const leitor = new FileReader(); leitor.onload = () => { setImagem({ nomeArquivo: arquivo.name, caminhoLocal: caminho, dataUrl: String(leitor.result || '') }); setCandidatos([]); setMensagem('Imagem carregada. Ajuste a régua e clique em “Calcular proximidade”.'); }; leitor.onerror = () => setMensagem('Não foi possível ler a imagem arrastada.'); leitor.readAsDataURL(arquivo); }; useEffect(() => { const sobre = (evento: DragEvent) => { if (evento.dataTransfer?.types.includes('Files')) { evento.preventDefault(); setArrastando(true); } }; const solto = (evento: DragEvent) => { if (!evento.dataTransfer?.files?.length) return; evento.preventDefault(); setArrastando(false); carregarArquivo(evento.dataTransfer.files[0]); }; window.addEventListener('dragover', sobre); window.addEventListener('drop', solto); return () => { window.removeEventListener('dragover', sobre); window.removeEventListener('drop', solto); }; }, []); const confrontar = () => { if (!imagem) return; setMensagem(`Calculando candidatos com limiar mínimo de ${limiar}%...`); api.confrontarImagem(imagem.caminhoLocal, limiar).then(resultado => { setCandidatos(resultado.candidatos || []); setMensagem(resultado.ok ? `Confronto concluído pelo motor ${resultado.motor}. ${resultado.candidatos?.length || 0} candidato(s) acima de ${resultado.limiarSemelhanca ?? limiar}%. A validação humana é obrigatória.` : resultado.mensagem); }).catch(erro => setMensagem(`Falha ao executar o confronto: ${erro.message || erro}`)); }; return <div className="confronto-imagem painel"><div className="titulo-painel"><p className="eyebrow">Confronto facial local</p><h3>Confrontar foto enviada com o banco</h3><p className="muted">O Buffalo organiza candidatos por semelhança. O limiar apenas filtra a triagem; não confirma identidade. A decisão final é humana.</p></div><div className={`zona-arrastar-imagem${arrastando ? ' arrastando' : ''}`}><strong>{arrastando ? 'Solte a imagem em qualquer lugar da janela' : 'Arraste a imagem para qualquer lugar da janela'}</strong><span>Não é necessário clicar nesta caixa. O botão abaixo é apenas uma alternativa.</span></div><div className="regua-semelhanca"><label htmlFor="limiar-semelhanca">Limiar mínimo de semelhança: <strong>{limiar}%</strong></label><input id="limiar-semelhanca" type="range" min="50" max="95" step="5" value={limiar} onChange={e => { setLimiar(Number(e.target.value)); setCandidatos([]); }} /><div className="regua-semelhanca-marcadores"><span>50% · triagem ampla</span><span>60%</span><span>95% · triagem restrita</span></div></div><div className="confronto-acoes"><button className="primario" onClick={selecionar}>Selecionar foto</button><button onClick={confrontar} disabled={!imagem}>Calcular proximidade</button></div>{imagem && <div className="imagem-fonte"><img src={imagem.dataUrl} alt="Imagem selecionada para confronto" /><div><strong>{imagem.nomeArquivo}</strong><p className="muted">Imagem de referência selecionada localmente.</p></div></div>}{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}{candidatos.length > 0 && <div className="grade-candidatos">{candidatos.map(item => <div className="candidato-imagem" key={item.id}>{item.dataUrl && <img className="candidato-imagem-preview" src={item.dataUrl} alt={`Imagem encontrada: ${item.nome}`} />}<div><strong>{item.nome}</strong><span>{item.idCaso} · Talão {item.talao}</span><small>{item.classificacao} · Distância: {Number(item.distancia ?? 1).toFixed(4)} · {item.similaridade}% de proximidade · acima do limiar selecionado</small></div><button onClick={() => api.abrirFoto(item.caminhoLocal)}>Abrir foto</button></div>)}</div>}</div>; }

function FluxoPainelPersistente({ caso }: { caso: any }) { const dados = JSON.parse(caso.dados_json || '{}'); const respostasSalvas = dados.respostasArvore || {}; const respostasIniciais = Object.fromEntries([...fluxoCabineVerde.flatMap(item => item.perguntas), ...Object.values(ARVORE_DECISAO_CONFIG.subabas).flatMap((item: any) => item.perguntas)].map((pergunta: any) => [pergunta.id, respostasSalvas[pergunta.id] || valorAutoPreenchido(pergunta, dados)]).filter(([, valor]) => valor)); const [respostas, setRespostas] = useState<Record<string, string>>(respostasIniciais); const [complementos, setComplementos] = useState<Record<string, string>>(dados.complementosArvore || {}); const [painel, setPainel] = useState(0); const [mensagem, setMensagem] = useState(''); const idade = extrairIdade(respostas, dados); const faixa = calcularFaixaEtaria(idade); const subaba = ARVORE_DECISAO_CONFIG.subabas[faixa]; const bloco = fluxoCabineVerde[painel]; const perguntas = painel === 1 && idade > 0 && subaba ? [...bloco.perguntas, ...subaba.perguntas] : bloco.perguntas; const alterar = (id: string, valor: string, complemento: string) => { setRespostas(anterior => ({ ...anterior, [id]: valor })); setComplementos(anterior => ({ ...anterior, [id]: complemento })); }; const salvar = () => api.salvarPainelArvore({ idCaso: caso.id_caso, painel: nomesPaineis[painel], respostas, complementos, operador: 'sessao-local' }).then(resultado => setMensagem(resultado.ok ? `Painel salvo em ${new Date(resultado.dataHora).toLocaleString('pt-BR')}.` : resultado.mensagem)); return <div className="fluxo-painel"><div className="prioridade-status"><span>{nomesPaineis[painel]}</span><b>{Object.values(respostas).filter(Boolean).length} respostas preenchidas</b></div><div className="navegacao-paineis">{nomesPaineis.map((nome, indice) => <button key={nome} className={painel === indice ? 'ativo' : ''} onClick={() => setPainel(indice)}>{nome}</button>)}</div><div className="painel-perguntas"><div className="titulo-painel"><p className="eyebrow">Edição por painel · {painel + 1} de {fluxoCabineVerde.length}</p><h3>{nomesPaineis[painel]}</h3><p className="muted">{painel === 1 && subaba ? `Perguntas específicas para ${faixa}.` : 'Dados preenchidos podem ser alterados e salvos a qualquer momento.'}</p></div>{painel === 1 && subaba && <div className="subfluxo-painel"><p className="eyebrow">Subfluxo da idade: {faixa}</p><h3>{subaba.titulo}</h3></div>}{perguntas.map((pergunta: any) => <div className="pergunta-painel" key={pergunta.id}><Question pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} /></div>)}</div><div className="acoes-arvore"><button onClick={() => setPainel(Math.max(0, painel - 1))} disabled={painel === 0}>Painel anterior</button><button onClick={salvar} className="primario">Salvar painel</button><button className="primario" onClick={() => setPainel(Math.min(fluxoCabineVerde.length - 1, painel + 1))} disabled={painel === fluxoCabineVerde.length - 1}>Próximo painel</button></div>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}</div>; }

function BuscaTalao() { const [termo, setTermo] = useState(''); const [resultados, setResultados] = useState<any[]>([]); const [pagina, setPagina] = useState(0); const [caso, setCaso] = useState<any>(); const porPagina = 10; const buscar = () => api.listarCasos(termo).then(itens => { setResultados(itens); setPagina(0); setCaso(undefined); }); useEffect(() => { buscar(); }, []); const selecionar = (id: string) => api.carregarCaso(id).then(setCaso).catch(erro => window.alert(erro.message)); const paginaAtual = resultados.slice(pagina * porPagina, pagina * porPagina + porPagina); const totalPaginas = Math.max(1, Math.ceil(resultados.length / porPagina)); const statusOperacional = statusConsulta; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Consulta operacional</p><h2>Buscar talão</h2><p>Selecione um dos últimos talões ou pesquise manualmente para editar os dados preenchidos.</p></div></div><div className="painel busca-talão"><div className="busca"><input autoFocus value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Digite o talão, cadastro ou nome" /><button className="primario" onClick={buscar}>Buscar talão</button></div>{!caso && <><div className="titulo-lista-consulta"><strong>{termo.trim() ? 'Resultados da busca' : '10 últimos talões'}</strong><span>{resultados.length} registro(s)</span></div>{paginaAtual.length ? <div className="lista-resultados-talao">{paginaAtual.map(item => { const status = statusOperacional(item); return <button className={`resultado-talao resultado-talao--${status.classe}`} key={item.idCaso} onClick={() => selecionar(item.idCaso)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · Talão {item.talaoPMESP || 'não informado'} · {status.rotulo}</span><small>{(() => { try { const dados = JSON.parse(item.dadosJson || '{}'); return (dados.vitimas || []).filter((vitima: any) => vitima.statusAtual).map((vitima: any) => `${vitima.pessoa?.nomeOriginal || vitima.pessoa?.nome || vitima.nome || 'Vítima'}: ${vitima.statusAtual}`).join(' · '); } catch { return ''; } })()}</small><small>{status.classe === 'localizado' ? 'Ocorrência encerrada · clique para consultar' : 'Clique para editar os dados preenchidos'}</small></button>; })}</div> : <p className="muted">Nenhum caso encontrado.</p>}<div className="paginacao-consulta"><button onClick={() => setPagina(Math.max(0, pagina - 1))} disabled={pagina === 0}>Anterior</button><span>Página {pagina + 1} de {totalPaginas}</span><button onClick={() => setPagina(Math.min(totalPaginas - 1, pagina + 1))} disabled={pagina >= totalPaginas - 1}>Próxima</button></div></>}{caso && <div className="editor-consulta"><div className="caso-titulo"><div><p className="eyebrow">Edição do caso</p><h3>{caso.nome_desaparecido || caso.id_caso}</h3><p className="muted">{caso.id_caso} · Talão {caso.talao_pm || 'não informado'}</p></div><button onClick={buscar}>Voltar para os talões</button></div><p className="muted">Cada painel pode ser salvo independentemente. A gravação registra data, hora, operador e painel no histórico local.</p><FluxoPainelPersistente key={caso.id_caso} caso={caso} /><ConsultaCompleta key={`consulta-${caso.id_caso}`} idCaso={caso.id_caso} api={api} rotulos={Object.fromEntries([...fluxoCabineVerde.flatMap(bloco => bloco.perguntas), ...Object.values(ARVORE_DECISAO_CONFIG.subabas).flatMap((bloco: any) => bloco.perguntas)].map((pergunta: any) => [pergunta.id, pergunta.texto || pergunta.pergunta || pergunta.id]))} /></div>}</div></section>; }

function TrabalhoComAtalhoImagem() { return <><div className="atalho-imagem-area"><BuscaImagens /></div><TrabalhoSequencial /></>; }

function AppBuscaImagem() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardIndices /> : aba === 'trabalho' ? <TrabalhoComAtalhoImagem /> : <AuditoriaFinal />}</main></div>; }

const nomesPaineis = fluxoCabineVerde.map(item => item.titulo);
const idsEntrevistaInicial = new Set([
  'p1', 'p2', 'p6', 'p7', 'p17', 'p19', 'p20', 'p21',
  'p26', 'p27', 'p28', 'p38', 'p40', 'p45',
  'p107', 'p109', 'p110', 'p117', 'p120', 'p288', 'p289', 'p290', 'p291'
]);

const camposEssenciaisEntrevistaInicial = [
  { id: 'cpf', rotulo: 'CPF do desaparecido', tipo: 'text' },
  { id: 'rg', rotulo: 'RG do desaparecido', tipo: 'text' },
  { id: 'dataNascimento', rotulo: 'Data de nascimento', tipo: 'date' },
  { id: 'telefoneDesaparecido', rotulo: 'Telefone do desaparecido', tipo: 'tel' },
  { id: 'nomeSolicitante', rotulo: 'Nome do solicitante', tipo: 'text' },
  { id: 'telefoneSolicitante', rotulo: 'Telefone do solicitante', tipo: 'tel' },
  { id: 'vinculoSolicitante', rotulo: 'Vínculo do solicitante', tipo: 'text', placeholder: 'Ex.: pai, mãe, irmão, amigo' },
  { id: 'historicoBreve', rotulo: 'Histórico breve', tipo: 'textarea' },
  { id: 'caracteristicas', rotulo: 'Características', tipo: 'textarea' }
];

function CamposEssenciaisEntrevistaInicial({ respostas, dados, aoAlterar }: { respostas: Record<string, string>; dados: Record<string, string>; aoAlterar: (id: string, valor: string) => void }) {
  return <div className="campos-essenciais-inicial"><div className="campos-essenciais-inicial__cabecalho"><div><p className="eyebrow">Dados essenciais</p><h3>Identificação e contato</h3></div><span>Preenchimento reutilizado automaticamente</span></div><div className="grade-campos-inicial">{camposEssenciaisEntrevistaInicial.map(campo => <label className={campo.tipo === 'textarea' ? 'campo-inicial-largo' : ''} key={campo.id}>{campo.rotulo}{campo.tipo === 'textarea' ? <textarea value={respostas[campo.id] || dados[campo.id] || ''} onChange={e => aoAlterar(campo.id, e.target.value)} placeholder={campo.id === 'historicoBreve' ? 'Resumo objetivo do desaparecimento e da última informação conhecida.' : 'Características físicas, roupas ou sinais úteis à localização.'} /> : <input type={campo.tipo} value={respostas[campo.id] || dados[campo.id] || ''} onChange={e => aoAlterar(campo.id, e.target.value)} placeholder={campo.placeholder} />}</label>)}</div></div>;
}

function ModalPosSalvamento({ aoContinuar, aoNovoCaso }: { aoContinuar: () => void; aoNovoCaso: () => void }) {
  return <div className="modal-fundo" role="dialog" aria-modal="true" aria-labelledby="titulo-salvamento">
    <div className="modal-confirmacao"><p className="eyebrow">Gravação confirmada</p><h3 id="titulo-salvamento">Dados salvos no banco</h3><p>As respostas da vítima até este momento foram registradas e permanecerão disponíveis para consulta.</p><p className="muted">Deseja limpar a tela para iniciar um novo caso?</p><div className="acoes-modal"><button onClick={aoContinuar}>Continuar neste caso</button><button className="primario" onClick={aoNovoCaso}>Sim, iniciar novo caso</button></div></div>
  </div>;
}

function EntrevistaInicial({ caso, aoNovoCaso = () => undefined, operador = 'sessao-local' }: { caso: any; aoNovoCaso?: () => void; operador?: string }) {
  const dados = obterRespostasUnificadas(caso);
  const perguntas = fluxoCabineVerde.flatMap(item => item.perguntas).filter((pergunta: any) => idsEntrevistaInicial.has(pergunta.id));
  const respostasIniciais = Object.fromEntries(perguntas.map((pergunta: any) => [pergunta.id, valorAutoPreenchido(pergunta, dados)]).filter(([, valor]) => valor));
  const [respostas, setRespostas] = useState<Record<string, string>>(respostasIniciais);
  const [complementos, setComplementos] = useState<Record<string, string>>({});
  const [mensagem, setMensagem] = useState('');
  const [salvamentoConfirmado, setSalvamentoConfirmado] = useState(false);
  const [statusAtendimento, setStatusAtendimento] = useState<'Em andamento' | 'Em triagem'>(caso.statusAtendimento === 'Em triagem' ? 'Em triagem' : 'Em andamento');
  const alterar = (id: string, valor: string, complemento: string) => {
    setRespostas(anterior => ({ ...anterior, [id]: valor }));
    setComplementos(anterior => ({ ...anterior, [id]: complemento }));
    if (valor.trim()) setStatusAtendimento('Em triagem');
    registrarRespostaUnificada(id, valor, complemento);
  };
  const salvar = () => api.salvarPainelArvore({ idCaso: caso.id_caso, painel: 'ENTREVISTA_INICIAL', statusAtendimento, respostas: { ...respostas, __nomeCaso: caso.nome_desaparecido || '', __talaoPMESP: caso.talao_pm || '', __dataTalao: caso.data_talao || '', __horaTalao: caso.hora_talao || '', __naturezaOcorrencia: caso.natureza_ocorrencia || '' }, complementos, nome: caso.nome_desaparecido || '', talaoPMESP: caso.talao_pm || '', dataTalao: caso.data_talao || '', operador })
    .then(resultado => { if (!resultado.ok) { setMensagem(resultado.mensagem); return; } const idPersistido = String(resultado.caso?.id || caso.id_caso); api.corrigirCaso({ idCaso: idPersistido, campos: { statusAtendimento, status: statusAtendimento }, justificativa: `Classificação operacional: ${statusAtendimento}`, operador }).then(atualizacao => { setMensagem(atualizacao.ok ? 'Entrevista inicial salva. Status do atendimento atualizado.' : 'Entrevista inicial salva, mas o status não pôde ser atualizado.'); }); if (resultado.confirmadoNoBanco) setSalvamentoConfirmado(true); });

  return <div className="entrevista-inicial">
    <div className="entrevista-inicial__cabecalho">
      <div>
        <p className="eyebrow">Fase 1 · localização imediata</p>
        <h3>Entrevista inicial</h3>
        <p>Registre somente o que ajuda a localizar a pessoa e identificar riscos urgentes. A entrevista qualificada pode continuar depois.</p>
      </div>
      <span className="entrevista-inicial__badge">Prioridade operacional</span>
    </div>
    <CamposEssenciaisEntrevistaInicial respostas={respostas} dados={dados} aoAlterar={(id, valor) => alterar(id, valor, '')} />
    <div className="painel-perguntas entrevista-inicial__painel">
      <div className="titulo-painel">
        <p className="eyebrow">Perguntas essenciais · {perguntas.length} itens</p>
        <h3>Comece pela informação acionável</h3>
        <p className="muted">Use “Não informado” quando a fonte não souber responder. Não interrompa a busca por dados complementares.</p>
      </div>
      {perguntas.map((pergunta: any) => <div className="pergunta-painel" key={pergunta.id}>
        {valorAutoPreenchido(pergunta, dados) && <span className="selo-legado">Preenchida automaticamente</span>}
        <Question pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} />
      </div>)}
    </div>
    <div className="acoes-arvore entrevista-inicial__acoes">
      <span>{Object.values(respostas).filter(Boolean).length} respostas preenchidas</span>
      <label>Status do atendimento<select value={statusAtendimento} onChange={e => setStatusAtendimento(e.target.value as 'Em andamento' | 'Em triagem')}><option value="Em andamento">Em andamento</option><option value="Em triagem">Em triagem</option></select></label>
      <button className="primario" onClick={salvar}>Salvar entrevista inicial</button>
    </div>
    {mensagem && <p className="mensagem-salvamento">{mensagem}</p>}
    {salvamentoConfirmado && <ModalPosSalvamento aoContinuar={() => setSalvamentoConfirmado(false)} aoNovoCaso={aoNovoCaso} />}
  </div>;
}

function FluxoEntrevistas({ caso, aoNovoCaso = () => undefined, operador = 'sessao-local' }: { caso: any; aoNovoCaso?: () => void; operador?: string }) {
  const [modo, setModo] = useState<'inicial' | 'qualificada'>('inicial');
  return <div className={`fluxo-entrevistas modo-${modo}`}>
    <div className="entrevista-switcher" role="tablist" aria-label="Fases da entrevista">
      <button className={modo === 'inicial' ? 'ativo' : ''} onClick={() => setModo('inicial')} role="tab" aria-selected={modo === 'inicial'}><strong>Entrevista inicial</strong><small>Localização e risco imediato</small></button>
      <button className={modo === 'qualificada' ? 'ativo' : ''} onClick={() => setModo('qualificada')} role="tab" aria-selected={modo === 'qualificada'}><strong>Entrevista qualificada</strong><small>Investigação e aprofundamento</small></button>
    </div>
    {modo === 'inicial' ? <EntrevistaInicial caso={caso} aoNovoCaso={aoNovoCaso} operador={operador} /> : <FluxoPainelPrioridade key={`qualificada-${caso.id_caso}`} caso={caso} aoNovoCaso={aoNovoCaso} />}
  </div>;
}

function FluxoPainelPrioridade({ caso, aoNovoCaso = () => undefined, operador = 'sessao-local' }: { caso: any; aoNovoCaso?: () => void; operador?: string }) { const dados = obterRespostasUnificadas(caso); const respostasIniciais = Object.fromEntries([...fluxoCabineVerde.flatMap(item => item.perguntas), ...Object.values(ARVORE_DECISAO_CONFIG.subabas).flatMap((item: any) => item.perguntas)].map((pergunta: any) => [pergunta.id, valorAutoPreenchido(pergunta, dados)]).filter(([, valor]) => valor)); const [respostas, setRespostas] = useState<Record<string, string>>(respostasIniciais); const [complementos, setComplementos] = useState<Record<string, string>>({}); const [painel, setPainel] = useState(0); const [mensagem, setMensagem] = useState(''); const [salvamentoConfirmado, setSalvamentoConfirmado] = useState(false); const idade = extrairIdade(respostas, dados); const faixa = calcularFaixaEtaria(idade); const subaba = ARVORE_DECISAO_CONFIG.subabas[faixa]; const bloco = fluxoCabineVerde[painel]; const perguntasVisiveis = painel === 1 && idade > 0 && subaba ? [...bloco.perguntas, ...subaba.perguntas] : bloco.perguntas; const alterar = (id: string, valor: string, complemento: string) => { setRespostas(anterior => ({ ...anterior, [id]: valor })); setComplementos(anterior => ({ ...anterior, [id]: complemento })); registrarRespostaUnificada(id, valor, complemento); }; const salvar = () => api.salvarPainelArvore({ idCaso: caso.id_caso, painel: nomesPaineis[painel], respostas: { ...respostas, __nomeCaso: caso.nome_desaparecido || '', __talaoPMESP: caso.talao_pm || '', __dataTalao: caso.data_talao || '' }, complementos, operador }).then(resultado => { setMensagem(resultado.ok ? `Entrevista qualificada salva e confirmada no banco em ${new Date(resultado.dataHora).toLocaleString('pt-BR')}.` : resultado.mensagem); if (resultado.ok && resultado.confirmadoNoBanco) setSalvamentoConfirmado(true); }); const risco = ['passo4_suspeita_crime', 'passo4_conflito', 'passo4_intencao_fuga'].some(id => respostas[id] === 'Sim') ? 'Prioridade elevada' : 'Triagem inicial'; return <div className="fluxo-painel"><div className="prioridade-status"><span>{risco}</span><b>{Object.values(respostas).filter(Boolean).length} respostas preenchidas</b></div><div className="navegacao-paineis">{nomesPaineis.map((nome, indice) => <button key={nome} className={painel === indice ? 'ativo' : ''} onClick={() => setPainel(indice)}>{nome}</button>)}</div><div className="painel-perguntas"><div className="titulo-painel"><p className="eyebrow">Entrevista qualificada · etapa {painel + 1} de {fluxoCabineVerde.length}</p><h3>{nomesPaineis[painel]}</h3><p className="muted">{painel === 1 && subaba ? `Perguntas específicas para ${faixa}.` : 'Preencha as informações disponíveis neste bloco.'}</p></div>{painel === 1 && subaba && <div className="subfluxo-painel"><p className="eyebrow">Fluxo definido pela idade: {faixa}</p><h3>{subaba.titulo}</h3></div>}{perguntasVisiveis.map((pergunta: any) => <div className="pergunta-painel" key={pergunta.id}>{valorAutoPreenchido(pergunta, { ...dados, nome_desaparecido: caso.nome_desaparecido }) && <span className="selo-legado">Preenchida do legado</span>}<Question pergunta={pergunta} valor={respostas[pergunta.id] || valorAutoPreenchido(pergunta, { ...dados, nome_desaparecido: caso.nome_desaparecido })} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} /></div>)}</div><div className="acoes-arvore"><button onClick={() => setPainel(Math.max(0, painel - 1))} disabled={painel === 0}>Painel anterior</button><button onClick={salvar} className="primario">Salvar entrevista qualificada</button><button className="primario" onClick={() => setPainel(Math.min(fluxoCabineVerde.length - 1, painel + 1))} disabled={painel === fluxoCabineVerde.length - 1}>Próximo painel</button></div>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}{salvamentoConfirmado && <ModalPosSalvamento aoContinuar={() => setSalvamentoConfirmado(false)} aoNovoCaso={aoNovoCaso} />}</div>; }

function VitimasCaso({ caso }: { caso: any }) { const [vitimas, setVitimas] = useState<any[]>([]); const [mensagem, setMensagem] = useState(''); const carregar = () => api.listarVitimasCaso(caso.id_caso).then(setVitimas); useEffect(() => { carregar(); }, [caso.id_caso]); const adicionar = () => api.adicionarVitima({ idCaso: caso.id_caso, operador: 'sessao-local' }).then(resultado => { setMensagem(resultado.ok ? `Vítima ${resultado.ordem} criada no mesmo caso e talão.` : resultado.mensagem); if (resultado.ok) carregar(); }); return <div className="vitimas-caso painel"><div><p className="eyebrow">Múltiplas vítimas</p><h3>Vítimas vinculadas ao mesmo caso</h3><p className="muted">Use após as buscas preliminares para incluir outra pessoa sem criar novo caso ou talão.</p></div><div className="lista-vitimas-caso">{vitimas.length ? vitimas.map(vitima => <div className="linha-vitima" key={vitima.id}><strong>Vítima {vitima.ordem}</strong><span>{vitima.nome || 'Identificação ainda não preenchida'}</span></div>) : <p className="muted">A primeira vítima será registrada no fluxo principal.</p>}</div><button className="primario" onClick={adicionar}>＋ Nova vítima no mesmo caso</button>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}</div>; }
function FluxoPainelVitima({ caso, vitima, aoSalvar }: { caso: any; vitima: any; aoSalvar: () => void }) { const dados = JSON.parse(vitima.dados_json || '{}'); const respostasIniciais = dados.respostasArvore || {}; const [respostas, setRespostas] = useState<Record<string, string>>(respostasIniciais); const [complementos, setComplementos] = useState<Record<string, string>>(dados.complementosArvore || {}); const [painel, setPainel] = useState(0); const [mensagem, setMensagem] = useState(''); const idade = extrairIdade(respostas, dados); const faixa = calcularFaixaEtaria(idade); const subaba = ARVORE_DECISAO_CONFIG.subabas[faixa]; const bloco = fluxoCabineVerde[painel]; const perguntas = painel === 1 && idade > 0 && subaba ? [...bloco.perguntas, ...subaba.perguntas] : bloco.perguntas; const alterar = (id: string, valor: string, complemento: string) => { setRespostas(anterior => ({ ...anterior, [id]: valor })); setComplementos(anterior => ({ ...anterior, [id]: complemento })); }; const salvar = () => api.salvarVitima({ idCaso: caso.id_caso, idVitima: vitima.id || vitima.idVitima, painel: nomesPaineis[painel], respostas, complementos, operador: 'sessao-local' }).then(resultado => { setMensagem(resultado.ok ? `Vítima ${vitima.ordem} salva em ${new Date(resultado.dataHora).toLocaleString('pt-BR')}. As respostas ficarão disponíveis nas próximas consultas.` : resultado.mensagem); if (resultado.ok) aoSalvar(); }); return <div className="fluxo-painel"><div className="prioridade-status"><span>Vítima {vitima.ordem} · {nomesPaineis[painel]}</span><b>{Object.values(respostas).filter(Boolean).length} respostas preenchidas</b></div><div className="navegacao-paineis">{nomesPaineis.map((nome, indice) => <button key={nome} className={painel === indice ? 'ativo' : ''} onClick={() => setPainel(indice)}>{nome}</button>)}</div><div className="painel-perguntas"><div className="titulo-painel"><p className="eyebrow">Qualificação da vítima · etapa {painel + 1} de {fluxoCabineVerde.length}</p><h3>{nomesPaineis[painel]}</h3><p className="muted">Respostas anteriores desta vítima são carregadas automaticamente. Altere somente se houver nova informação.</p></div>{painel === 1 && subaba && <div className="subfluxo-painel"><p className="eyebrow">Subfluxo da idade: {faixa}</p><h3>{subaba.titulo}</h3></div>}{perguntas.map((pergunta: any) => <div className="pergunta-painel" key={pergunta.id}><Question pergunta={pergunta} valor={respostas[pergunta.id] || ''} complemento={complementos[pergunta.id] || ''} onChange={(valor, complemento) => alterar(pergunta.id, valor, complemento)} /></div>)}</div><div className="acoes-arvore"><button onClick={() => setPainel(Math.max(0, painel - 1))} disabled={painel === 0}>Painel anterior</button><button onClick={salvar} className="primario">Salvar vítima</button><button onClick={() => setPainel(Math.min(fluxoCabineVerde.length - 1, painel + 1))} className="primario" disabled={painel === fluxoCabineVerde.length - 1}>Próximo painel</button></div>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}</div>; }
function VitimasCasoSelecionavel({ caso, aoSelecionar }: { caso: any; aoSelecionar: (vitima: any) => void }) { const [vitimas, setVitimas] = useState<any[]>([]); const [mensagem, setMensagem] = useState(''); const carregar = () => api.listarVitimasCaso(caso.id_caso).then(setVitimas); useEffect(() => { carregar(); }, [caso.id_caso]); const adicionar = () => api.adicionarVitima({ idCaso: caso.id_caso, operador: 'sessao-local' }).then(resultado => { if (!resultado.ok) { setMensagem(resultado.mensagem); return; } setMensagem(`Vítima ${resultado.ordem} criada. Agora selecione “Preencher” para abrir as perguntas.`); carregar(); }); return <div className="vitimas-caso painel"><div><p className="eyebrow">Múltiplas vítimas</p><h3>Vítimas vinculadas ao mesmo caso</h3><p className="muted">Cada vítima recebe suas próprias respostas, fotos e desfecho. O talão permanece único.</p></div><div className="lista-vitimas-caso">{vitimas.length ? vitimas.map(vitima => <div className="linha-vitima" key={vitima.id}><div><strong>Vítima {vitima.ordem}</strong><span>{JSON.parse(vitima.dados_json || '{}').nomeCompletoDesaparecido || vitima.nome || 'Identificação ainda não preenchida'}</span></div><button className="botao-vitima" onClick={() => aoSelecionar(vitima)}>Preencher / editar</button></div>) : <p className="muted">A primeira vítima é preenchida no fluxo principal.</p>}</div><button className="primario" onClick={adicionar}>＋ Nova vítima no mesmo caso</button>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}</div>; }
function NovaAnaliseF2({ operador }: { operador: Operador }) {
  const agora = new Date();
  const respostasUnificadas = obterRespostasUnificadas({});
  const [aberta, setAberta] = useState(false);
  const [pessoa, setPessoa] = useState<PessoaF2 | null>(null);
  const [resultados, setResultados] = useState<PessoaF2[]>([]);
  const [analises, setAnalises] = useState<AnaliseF2[]>([]);
  const [mensagem, setMensagem] = useState('');
  const [busca, setBusca] = useState({ nome: '', cpf: '', rg: '', dataTalao: '', talao: '', status: '', condicao: '', estagio: '', contato: '' });
  const [form, setForm] = useState({ dataHoraAnalise: agora.toISOString().slice(0, 16), dataTalao: agora.toISOString().slice(0, 10), horaTalao: '', talao: '', nome: respostasUnificadas.nome || respostasUnificadas.nomeCompletoDesaparecido || '', cpf: respostasUnificadas.cpf || '', rg: respostasUnificadas.rg || '', dataNascimento: respostasUnificadas.dataNascimento || '', idade: respostasUnificadas.idade || '', telefone: respostasUnificadas.telefone || respostasUnificadas.telefoneDesaparecido || '', nomeSolicitante: respostasUnificadas.nomeSolicitante || '', telefoneSolicitante: respostasUnificadas.telefoneSolicitante || '', natureza: '', caracteristicasBasicas: respostasUnificadas.caracteristicasBasicas || respostasUnificadas.caracteristicasMarcantes || '', endereco: respostasUnificadas.endereco || '', sentidoTomado: respostasUnificadas.sentidoTomado || respostasUnificadas.destinoProvavel || '', historicoF2: respostasUnificadas.historicoF2 || '', observacoes: respostasUnificadas.observacoesOperacionais || '', situacaoInformada: '' as SituacaoPessoa | '' });
  const [marcadores, setMarcadores] = useState<Record<string, boolean>>({});
  const atualizar = (campo: string, valor: string) => { registrarDadosF2Unificados({ [campo]: valor }); setForm(atual => ({ ...atual, [campo]: valor })); };
  const pesquisar = async () => { const termo = busca.nome || busca.cpf || busca.rg; const resposta = await api.buscarPessoasF2({ termo, dataTalao: busca.dataTalao, talao: busca.talao, status: busca.status, condicao: busca.condicao, estagio: busca.estagio, contato: busca.contato }); setResultados(resposta.pessoas || []); if (!resposta.ok) setMensagem(resposta.mensagem || 'Não foi possível pesquisar a base central.'); };
  const selecionarPessoa = (item: PessoaF2) => { setPessoa(item); setResultados([]); const dadosPessoa = { nome: item.nome, cpf: item.cpf || '', rg: item.rg || '', dataNascimento: item.dataNascimento || '', idade: (item as any).idade || '', telefone: item.telefone || '' }; registrarDadosF2Unificados(dadosPessoa); setForm(atual => ({ ...atual, ...dadosPessoa })); api.listarAnalisesF2(item.idPessoa).then(resposta => setAnalises(resposta.analises || [])); };
  const nova = () => { setAberta(true); setPessoa(null); setResultados([]); setAnalises([]); setMensagem(''); };
  const salvar = async () => {
    setMensagem('');
    let pessoaAtual = pessoa;
    if (!pessoaAtual) { if (!form.nome.trim()) return setMensagem('Selecione uma pessoa existente ou informe um nome para criar a pessoa.'); const respostaPessoa = await api.criarPessoaF2({ nome: form.nome, cpf: form.cpf, rg: form.rg, dataNascimento: form.dataNascimento, telefone: form.telefone, operador: operador.nome }); if (!respostaPessoa.ok) return setMensagem(respostaPessoa.mensagem || 'Não foi possível criar a pessoa.'); pessoaAtual = respostaPessoa.pessoa; setPessoa(pessoaAtual); }
    if (!form.dataHoraAnalise || !form.dataTalao || !form.talao || !operador.nome) return setMensagem('Preencha data/hora da análise, data do talão, talão e operador.');
    const resposta = await api.criarAnaliseF2({ ...form, idPessoa: pessoaAtual.idPessoa, idCaso: null, situacaoInformada: form.situacaoInformada || null, marcadoresAndamento: marcadores, origem: 'ANALISE_F2', operador: operador.nome });
    if (!resposta.ok) return setMensagem(resposta.mensagem || 'Não foi possível salvar a análise.');
    setAnalises(atual => [resposta.analise, ...atual]); setMensagem('Análise F2 salva e confirmada no banco central.');
  };
  const statusAtual = calcularStatusAtualPessoa(analises);
  const registrarQualificacao = async () => { if (!pessoa) return; const resumo = window.prompt('Resumo da qualificação:'); if (!resumo?.trim()) return; const resposta = await api.criarQualificacaoF2({ idPessoa: pessoa.idPessoa, idCaso: null, dataHora: new Date().toISOString(), operador: operador.nome, resumo, qualificacaoConcluida: false }); setMensagem(resposta.ok ? 'Qualificação registrada e auditada.' : resposta.mensagem); };
  const registrarPista = async () => { if (!pessoa) return; const descricao = window.prompt('Descrição da pista:'); if (!descricao?.trim()) return; const resposta = await api.criarPistaF2({ idPessoa: pessoa.idPessoa, idCaso: null, dataHora: new Date().toISOString(), origem: 'F2', descricao, confianca: 'INDETERMINADA', gerouAcaoOperacional: false, operador: operador.nome }); setMensagem(resposta.ok ? 'Pista registrada e auditada.' : resposta.mensagem); };
  return <section className="painel analise-f2-painel"><div className="cabecalho-secao"><div><p className="eyebrow">Entrada 2 · pesquisa SIOPM/F2</p><h3>Nova Análise F2</h3><p>Registro preliminar independente de caso; não exige a qualificação completa.</p></div><button className="primario" onClick={nova}>＋ NOVA ANÁLISE F2</button></div>{aberta && <div className="analise-f2-form"><div className="analise-f2-busca"><h4>Buscar pessoa antes de criar</h4><div className="grade-form"><label>Nome<input value={busca.nome} onChange={e => setBusca({ ...busca, nome: e.target.value })} onBlur={pesquisar} /></label><label>CPF<input value={busca.cpf} onChange={e => setBusca({ ...busca, cpf: e.target.value })} onBlur={pesquisar} /></label><label>RG<input value={busca.rg} onChange={e => setBusca({ ...busca, rg: e.target.value })} onBlur={pesquisar} /></label><label>Data do talão<input type="date" value={busca.dataTalao} onChange={e => setBusca({ ...busca, dataTalao: e.target.value })} /></label><label>Talão<input value={busca.talao} onChange={e => setBusca({ ...busca, talao: e.target.value })} /></label><label>Status<select value={busca.status} onChange={e => setBusca({ ...busca, status: e.target.value })}><option value="">Todos</option><option value="DESAPARECIDO">Desaparecido</option><option value="LOCALIZADO">Localizado</option><option value="CANCELADO">Cancelado</option><option value="OUTRO">Outro</option></select></label><label>Condição<select value={busca.condicao} onChange={e => setBusca({ ...busca, condicao: e.target.value })}><option value="">Todas</option><option value="PENDENTE_QUALIFICACAO">Pendente de qualificação</option><option value="EM_QUALIFICACAO">Em qualificação</option><option value="EM_ACOMPANHAMENTO">Em acompanhamento</option><option value="QUALIFICADA">Qualificada</option><option value="ENCERRADA">Encerrada</option><option value="SEM_ATENDIMENTO_F2">Sem atendimento F2</option></select></label><label>Em análise / estágio<select value={busca.estagio} onChange={e => setBusca({ ...busca, estagio: e.target.value })}><option value="">Todos</option><option value="APENAS_ANALISE_F2">Apenas análise F2</option><option value="ANALISE_F2_VINCULADA">Análise F2 vinculada</option><option value="CONTATO_REGISTRADO">Contato registrado</option><option value="QUALIFICACAO_INICIADA">Qualificação iniciada</option><option value="QUALIFICACAO_COMPLETA">Qualificação completa</option><option value="SEM_REGISTRO_F2">Sem registro F2</option></select></label><label>Contato telefônico<select value={busca.contato} onChange={e => setBusca({ ...busca, contato: e.target.value })}><option value="">Todos</option><option value="SIM">Sim</option><option value="NAO">Não</option></select></label><button type="button" onClick={pesquisar}>Pesquisar</button></div>{resultados.map(item => <button type="button" className="f2-pessoa-resultado" key={item.idPessoa} onClick={() => selecionarPessoa(item)}><strong>{item.nome}</strong><span>{item.rg || 'RG não informado'} · Status: {item.statusAtual || 'sem situação explícita'} · Condição: {item.condicao} · Estágio: {item.estagioAtendimento}</span></button>)}{pessoa && <p className="f2-pessoa-selecionada">Pessoa selecionada: <strong>{pessoa.nome}</strong> · {pessoa.idPessoa}</p>}</div><div className="analise-f2-blocos"><h4>Identificação do talão</h4><div className="grade-form"><label>Data da análise<input type="datetime-local" value={form.dataHoraAnalise} onChange={e => atualizar('dataHoraAnalise', e.target.value)} /></label><label>Data do talão<input type="date" value={form.dataTalao} onChange={e => atualizar('dataTalao', e.target.value)} /></label><label>Hora do talão<input type="time" value={form.horaTalao} onChange={e => atualizar('horaTalao', e.target.value)} /></label><label>Número do talão<input value={form.talao} onChange={e => atualizar('talao', e.target.value)} /></label><label>Natureza<input value={form.natureza} onChange={e => atualizar('natureza', e.target.value)} /></label></div><h4>Pessoa e contato</h4><div className="grade-form"><label>Nome<input value={form.nome} onChange={e => atualizar('nome', e.target.value)} /></label><label>CPF<input value={form.cpf} onChange={e => atualizar('cpf', e.target.value)} /></label><label>RG<input value={form.rg} onChange={e => atualizar('rg', e.target.value)} /></label><label>Data de nascimento<input type="date" value={form.dataNascimento} onChange={e => atualizar('dataNascimento', e.target.value)} /></label><label>Telefone encontrado<input value={form.telefone} onChange={e => atualizar('telefone', e.target.value)} /></label><label>Nome do solicitante<input value={form.nomeSolicitante} onChange={e => atualizar('nomeSolicitante', e.target.value)} /></label><label>Telefone do solicitante<input value={form.telefoneSolicitante} onChange={e => atualizar('telefoneSolicitante', e.target.value)} /></label></div><h4>Contexto preliminar</h4><div className="grade-form"><label>Características básicas<textarea value={form.caracteristicasBasicas} onChange={e => atualizar('caracteristicasBasicas', e.target.value)} /></label><label>Endereço<textarea value={form.endereco} onChange={e => atualizar('endereco', e.target.value)} /></label><label>Sentido tomado<textarea value={form.sentidoTomado} onChange={e => atualizar('sentidoTomado', e.target.value)} /></label><label>Histórico relevante<textarea value={form.historicoF2} onChange={e => atualizar('historicoF2', e.target.value)} /></label><label>Observações<textarea value={form.observacoes} onChange={e => atualizar('observacoes', e.target.value)} /></label></div><h4>Situação explícita da vítima</h4><div className="grade-form"><label>Situação<select value={form.situacaoInformada} onChange={e => atualizar('situacaoInformada', e.target.value)}><option value="">Sem nova situação</option>{SITUACOES_PESSOA.map(item => <option key={item} value={item}>{item}</option>)}</select></label>{['fotoRecebida', 'triagemRealizada', 'contatoRealizado', 'tentativaContato', 'caixaPostal', 'semNovaInformacao', 'novaOcorrenciaEncontrada', 'informacaoRelevante'].map(item => <label className="f2-checkbox" key={item}><input type="checkbox" checked={Boolean(marcadores[item])} onChange={e => setMarcadores({ ...marcadores, [item]: e.target.checked })} />{item}</label>)}</div></div><div className="acoes-f2"><button className="primario" onClick={salvar}>Salvar Análise F2</button><button onClick={() => setAberta(false)}>Fechar</button></div>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}</div>}{pessoa && <div className="f2-linha-tempo"><h4>{pessoa.nome} · Status atual calculado: {statusAtual || 'sem situação explícita'}</h4><div className="acoes-f2"><button onClick={registrarQualificacao}>Registrar qualificação</button><button onClick={registrarPista}>Registrar pista</button></div>{analises.map(item => <article key={item.idAnalise}><strong>{new Date(item.dataHoraAnalise).toLocaleString('pt-BR')}</strong><span>Talão {item.talao} · {item.situacaoInformada || 'sem alteração explícita de status'}</span><small>{Object.entries(item.marcadoresAndamento || {}).filter(([, valor]) => valor).map(([chave]) => chave).join(' · ') || 'Sem marcadores de andamento'}</small></article>)}</div>}</section>;
}

function IdentificacaoCaso({ caso, aoAlterar }: { caso: any; aoAlterar: (campo: string, valor: string) => void }) { return <div className="identificacao-caso painel"><p className="eyebrow">Identificação do atendimento</p><div className="grade-form"><label>Nome da vítima<input value={caso.nome_desaparecido || ''} onChange={e => aoAlterar('nome_desaparecido', e.target.value)} placeholder="Nome completo" /></label><label>Data do talão<input type="date" value={caso.data_talao || ''} onChange={e => aoAlterar('data_talao', e.target.value)} /></label><label>Hora do talão<input type="time" value={caso.hora_talao || ''} onChange={e => aoAlterar('hora_talao', e.target.value)} /></label><label>Talão PMESP<input value={caso.talao_pm || ''} onChange={e => aoAlterar('talao_pm', e.target.value)} placeholder="Número do talão" /></label><label>Natureza da ocorrência<input value={caso.natureza_ocorrencia || ''} onChange={e => aoAlterar('natureza_ocorrencia', e.target.value)} placeholder="Ex.: desaparecimento de pessoa" /></label></div><p className="muted">Nome, data, hora, natureza e número do talão serão reutilizados nas entrevistas, consultas e fotos.</p></div>; }

function TrabalhoPainelPrioridade({ operador }: { operador: Operador }) { const [modo, setModo] = useState<'rapida' | 'qualificada'>('rapida'); const [caso, setCaso] = useState<any>(); const [vitimaAtiva, setVitimaAtiva] = useState<any>(); const novoCaso = () => { localStorage.removeItem(CHAVE_RESPOSTAS_PENDENTES); setCaso({ id_caso: 'NOVO-' + Date.now(), nome_desaparecido: '', data_talao: '', hora_talao: '', talao_pm: '', natureza_ocorrencia: '', origemEntrada: modo === 'rapida' ? 'ENTREVISTA_INICIAL' : 'CASO_190', tipoEntrada: modo === 'rapida' ? 'INSERCAO_RAPIDA' : 'INSERCAO_QUALIFICADA', dados_json: '{}' }); setVitimaAtiva(undefined); }; const alterarCaso = (campo: string, valor: string) => setCaso((atual: any) => ({ ...atual, [campo]: valor })); return <section className="area-trabalho-operacional"><div className="cabecalho-secao"><div><p className="eyebrow">Operação · área de trabalho</p><h2>Inserção de atendimento</h2><p>Escolha o nível de registro conforme a urgência. A foto da vítima está disponível nos dois fluxos.</p></div></div><div className="tipo-insercao" role="tablist" aria-label="Tipo de inserção"><button className={modo === 'rapida' ? 'ativo' : ''} onClick={() => setModo('rapida')} role="tab" aria-selected={modo === 'rapida'}><span className="tipo-insercao__numero">01</span><span><strong>Inserção rápida</strong><small>Localização imediata e riscos urgentes</small></span></button><button className={modo === 'qualificada' ? 'ativo' : ''} onClick={() => setModo('qualificada')} role="tab" aria-selected={modo === 'qualificada'}><span className="tipo-insercao__numero">02</span><span><strong>Inserção qualificada</strong><small>Investigação completa e aprofundamento</small></span></button></div>{!caso && <div className="painel escolha-insercao"><p className="eyebrow">Fluxo selecionado</p><h3>{modo === 'rapida' ? 'Começar inserção rápida' : 'Começar inserção qualificada'}</h3><p className="muted">{modo === 'rapida' ? 'Preencha primeiro o que ajuda a localizar a pessoa. Você poderá qualificar o mesmo caso depois.' : 'Registre a entrevista completa, reutilizando os dados já informados na inserção rápida.'}</p><button className="primario botao-novo-caso" onClick={novoCaso}>＋ {modo === 'rapida' ? 'INICIAR INSERÇÃO RÁPIDA' : 'INICIAR INSERÇÃO QUALIFICADA'}</button></div>}{caso && <div className="painel arvore area-trabalho-limpa"><div className="barra-fluxo-atual"><div><p className="eyebrow">{modo === 'rapida' ? 'Inserção rápida' : 'Inserção qualificada'} · {caso.id_caso}</p><h3>{modo === 'rapida' ? 'Localização imediata' : 'Investigação aprofundada'}</h3></div><button onClick={() => setCaso(undefined)}>Trocar tipo / novo atendimento</button></div><IdentificacaoCaso caso={caso} aoAlterar={alterarCaso} />{vitimaAtiva ? <><div className="caso-titulo"><div><p className="eyebrow">Caso {caso.id_caso} · Talão {caso.talao_pm || 'não informado'}</p><h3>Preenchimento da Vítima {vitimaAtiva.ordem}</h3></div><button onClick={() => setVitimaAtiva(undefined)}>Voltar para o caso</button></div><FluxoPainelVitima key={vitimaAtiva.id} caso={caso} vitima={vitimaAtiva} aoSalvar={() => undefined} /><FotoFinal caso={caso} operador={operador.nome} /></> : modo === 'rapida' ? <><EntrevistaInicial key={`rapida-${caso.id_caso}`} caso={caso} aoNovoCaso={novoCaso} operador={operador.nome} /><FotoFinal caso={caso} operador={operador.nome} /></> : <><FluxoPainelPrioridade key={`qualificada-${caso.id_caso}`} caso={caso} aoNovoCaso={novoCaso} operador={operador.nome} /><FotoFinal caso={caso} operador={operador.nome} /></>}<VitimasCasoSelecionavel caso={caso} aoSelecionar={setVitimaAtiva} /></div>}</section>; }

function AppPainelPrioridadeComConfiguracoes() { const [aba, setAba] = useState<Exclude<Aba, 'dashboard'>>('trabalho'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; const abas: [Exclude<Aba, 'dashboard'>, string][] = [ ['trabalho', 'Área de trabalho'], ['buscar-talao', 'Buscar talão'], ['buscar-imagem', 'Buscar imagem'], ['auditoria', 'Finalização e desfecho'], ['producao', 'Resumo mensal'], ['producao-diaria', 'Resumo diário'], ['andamento', 'Em andamento'], ['triagem', 'Em triagem'], ['localizacoes', 'Localizações'], ['configuracoes', 'Configurações']]; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{abas.map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'trabalho' ? <TrabalhoPainelPrioridade operador={operador} /> : aba === 'buscar-talao' ? <BuscaTalao /> : aba === 'buscar-imagem' ? <><BuscaImagens /><ConfrontoImagem /></> : aba === 'producao' ? <ProducaoMensalSqlite /> : aba === 'producao-diaria' ? <ProducaoDiaria api={api} operador={operador} modo="completo" /> : aba === 'andamento' ? <EmTriagem somenteSemAtividade /> : aba === 'triagem' ? <EmTriagem /> : aba === 'localizacoes' ? <Localizacoes /> : aba === 'configuracoes' ? <ConfiguracoesConexao /> : <AuditoriaFinal />}</main></div>; }

function ProducaoProcedimentos() { const [linhas, setLinhas] = useState<any[]>([]); const [carregando, setCarregando] = useState(true); const [erro, setErro] = useState(''); useEffect(() => { (api.listarProducaoConsolidada ? api.listarProducaoConsolidada() : Promise.resolve({ resumoMensal: [] })).then(resposta => setLinhas(resposta.resumoMensal || [])).catch((falha: any) => setErro(falha.message || 'Não foi possível consultar o consolidado.')).finally(() => setCarregando(false)); }, []); const campos = ['analiseCadastros', 'contatosDeclarantes', 'localizacoesTalao', 'transferencias6190', 'coletaFotos', 'transferenciaAudio', 'atualizacoesSiopm', 'ocorrenciasGeradas']; const total = (linha: any) => campos.reduce((soma, campo) => soma + Number(linha[campo] || 0), 0); const data = (valor: string) => valor ? new Date(`${valor}T12:00:00`).toLocaleDateString('pt-BR') : '—'; const totalCampos = (campo: string) => linhas.reduce((soma, linha) => soma + Number(linha[campo] || 0), 0); return <div className="painel tabela-producao tabela-procedimentos"><h3>PRODUÇÃO DA CABINE MURALHA PAULISTA DESAPARECIDOS</h3>{carregando ? <p className="carregando">Carregando dados consolidados...</p> : erro ? <p className="estado-vazio">{erro}</p> : <div className="tabela-producao-scroll"><table><thead><tr><th>DATA INÍCIO</th><th>DATA FINAL</th><th>DIAS TRABALHADOS</th><th>ANÁLISE DE CADASTROS (190)</th><th>CONTATOS COM DECLARANTES</th><th>LOCALIZAÇÃO/BAIXAS — TALÃO</th><th>LOCALIZAÇÕES / TRANSFERÊNCIAS 6190</th><th>COLETA DE FOTO</th><th>TRANSFERÊNCIA DE ÁUDIO 190</th><th>ATUALIZAÇÃO SIOPM WEB</th><th>OCORRÊNCIA GERADA</th><th>TOTAL DE INTERVENÇÕES</th></tr></thead><tbody>{linhas.map(linha => <tr key={linha.id}><td>{data(linha.dataInicio)}</td><td>{data(linha.dataFinal)}</td><td>{linha.diasTrabalhados}</td>{campos.map(campo => <td key={campo}>{linha[campo]}</td>)}<td><strong>{total(linha)}</strong></td></tr>)}</tbody><tfoot><tr><th colSpan={2}>TOTAL</th><th>{linhas.reduce((soma, linha) => soma + Number(linha.diasTrabalhados || 0), 0)}</th>{campos.map(campo => <th key={campo}>{totalCampos(campo)}</th>)}<th>{linhas.reduce((soma, linha) => soma + total(linha), 0)}</th></tr></tfoot></table></div>}</div>; }
function ProducaoProcedimentosCorrigida({ inicio, fim }: { inicio: string; fim: string }) {
  const campos = ['analiseCadastros', 'contatosDeclarantes', 'localizacoesTalao', 'transferencias6190', 'coletaFotos', 'transferenciaAudio', 'atualizacoesSiopm', 'ocorrenciasGeradas'];
  const [linhas, setLinhas] = useState<any[]>([]); const [carregando, setCarregando] = useState(true); const [erro, setErro] = useState('');
  const formatarData = (valor: unknown) => { const bruto = String(valor || '').trim(); const iso = bruto.match(/^(\d{4})-(\d{2})-(\d{2})/); const br = bruto.match(/^(\d{2})\/(\d{2})\/(\d{4})/); if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3])).toLocaleDateString('pt-BR'); if (br) return new Date(Number(br[3]), Number(br[2]) - 1, Number(br[1])).toLocaleDateString('pt-BR'); return '—'; };
  const consolidar = (resposta: any) => { const diarios = (resposta.registrosDiarios || []).filter((item: any) => String(item.data || '') >= inicio && String(item.data || '') <= fim); const mensais = [...(resposta.resumoMensal || [])]; const porMes = new Map<string, any[]>(); diarios.forEach((item: any) => { const mes = String(item.data || '').slice(0, 7); if (mes) porMes.set(mes, [...(porMes.get(mes) || []), item]); }); porMes.forEach((registros, mes) => { const existente = mensais.find((item: any) => String(item.dataInicio || '').slice(0, 7) === mes); const datas = [...new Set(registros.map(item => String(item.data || '').slice(0, 10)).filter(Boolean))].sort(); const temValores = existente && campos.some(campo => Number(existente[campo] || 0) > 0); if (temValores) { if (!Number(existente.diasTrabalhados)) existente.diasTrabalhados = datas.length; return; } const agregado: any = { id: `mensal-ui-${mes}`, dataInicio: datas[0] || `${mes}-01`, dataFinal: datas[datas.length - 1] || existente?.dataFinal || null, diasTrabalhados: datas.length }; campos.forEach(campo => { agregado[campo] = registros.reduce((soma, item) => soma + Number(item[campo] || 0), 0); }); if (existente) mensais[mensais.indexOf(existente)] = agregado; else mensais.push(agregado); }); return mensais.filter((item: any) => String(item.dataInicio || '') <= fim && String(item.dataFinal || item.dataInicio || '') >= inicio).sort((a: any, b: any) => String(a.dataInicio).localeCompare(String(b.dataInicio))); };
  useEffect(() => { setCarregando(true); setErro(''); (api.listarProducaoConsolidada ? api.listarProducaoConsolidada({ inicio, fim }) : Promise.resolve({ resumoMensal: [], registrosDiarios: [] })).then(resposta => setLinhas(consolidar(resposta))).catch((falha: any) => { setErro(falha.message || 'Não foi possível consultar o consolidado.'); setLinhas([]); }).finally(() => setCarregando(false)); }, [inicio, fim]);
  const total = (linha: any) => campos.reduce((soma, campo) => soma + Number(linha[campo] || 0), 0); const totalCampo = (campo: string) => linhas.reduce((soma, linha) => soma + Number(linha[campo] || 0), 0); const totalDias = linhas.reduce((soma, linha) => soma + Number(linha.diasTrabalhados || 0), 0);
  return <div className="painel tabela-producao tabela-procedimentos"><h3>PRODUÇÃO DA CABINE MURALHA PAULISTA DESAPARECIDOS</h3>{carregando ? <p className="carregando">Carregando dados consolidados...</p> : erro ? <p className="estado-vazio">{erro}</p> : <div className="tabela-producao-scroll"><table><thead><tr><th>DATA INÍCIO</th><th>DATA FINAL</th><th>DIAS TRABALHADOS</th><th>ANÁLISE DE CADASTROS (190)</th><th>CONTATOS COM DECLARANTES</th><th>LOCALIZAÇÃO/BAIXAS — TALÃO</th><th>LOCALIZAÇÕES / TRANSFERÊNCIAS 6190</th><th>COLETA DE FOTO</th><th>TRANSFERÊNCIA DE ÁUDIO 190</th><th>ATUALIZAÇÃO SIOPM WEB</th><th>OCORRÊNCIA GERADA</th><th>TOTAL DE INTERVENÇÕES</th></tr></thead><tbody>{linhas.map(linha => <tr key={linha.id}><td>{formatarData(linha.dataInicio)}</td><td>{formatarData(linha.dataFinal)}</td><td>{Number(linha.diasTrabalhados) > 0 ? linha.diasTrabalhados : '—'}</td>{campos.map(campo => <td key={campo}>{Number(linha[campo] || 0)}</td>)}<td><strong>{total(linha)}</strong></td></tr>)}</tbody><tfoot><tr><th colSpan={2}>TOTAL</th><th>{totalDias}</th>{campos.map(campo => <th key={campo}>{totalCampo(campo)}</th>)}<th>{linhas.reduce((soma, linha) => soma + total(linha), 0)}</th></tr></tfoot></table></div>}</div>;
}

function ProducaoMensalSqlite() { const [mesInicio, setMesInicio] = useState('2026-04'); const [mesFim, setMesFim] = useState('2026-08'); const [linhas, setLinhas] = useState<any[]>([]); const [carregando, setCarregando] = useState(true); const [erro, setErro] = useState(''); const inicio = (mes: string) => `${mes}-01`; const fim = (mes: string) => { const partes = mes.split('-').map(Number); return `${partes[0]}-${String(partes[1]).padStart(2, '0')}-${String(new Date(partes[0], partes[1], 0).getDate()).padStart(2, '0')}`; }; const data = (valor: string) => { const partes = String(valor || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return partes ? new Date(Number(partes[1]), Number(partes[2]) - 1, Number(partes[3])).toLocaleDateString('pt-BR') : '—'; }; const consultar = async () => { if (!mesInicio || !mesFim || mesInicio > mesFim) { setErro('Selecione um período válido.'); setLinhas([]); setCarregando(false); return; } setCarregando(true); setErro(''); try { const resposta = await api.listarProducaoConsolidada?.({ inicio: inicio(mesInicio), fim: fim(mesFim) }); setLinhas((resposta?.resumoMensal || []).map((linha: any) => ({ ...linha, inicio: linha.dataInicio, fim: linha.dataFinal, dias: linha.diasTrabalhados, painel: { total: linha.localizacaoDesaparecido ?? 0, categorias: [{ id: 'cabine', valor: linha.localizacoesCabine ?? 0 }, { id: 'vtr', valor: linha.localizacoesVtr ?? 0 }, { id: 'vultoOutros', valor: linha.localizacoesVultoOutros ?? 0 }, { id: 'preso', valor: linha.localizacoesPreso ?? 0 }, { id: 'obito', valor: linha.localizacoesObito ?? 0 }] } }))); } catch (falha: any) { setErro(falha.message || 'Não foi possível consultar o período.'); setLinhas([]); } finally { setCarregando(false); } }; useEffect(() => { consultar(); }, [mesInicio, mesFim]); const valor = (painel: any, id: string) => painel?.categorias?.find((item: any) => item.id === id)?.valor ?? 0; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Produção operacional</p><h2>Resumo mensal</h2><p>Indicadores mensais consultados diretamente no SQLite.</p></div><div className="dashboard-filtros"><label>Mês inicial<input type="month" value={mesInicio} onChange={e => setMesInicio(e.target.value)} /></label><label>Mês final<input type="month" value={mesFim} onChange={e => setMesFim(e.target.value)} /></label></div></div><div className="painel tabela-producao">{carregando ? <p className="carregando">Carregando produção...</p> : erro ? <p className="estado-vazio">{erro}</p> : <div className="tabela-producao-scroll"><table><thead><tr><th>DATA INÍCIO</th><th>DATA FINAL</th><th>DIAS TRABALHADOS</th><th>MURALHA</th><th>VTR PM</th><th>VULTO / IMPRENSA / OUTROS</th><th>PRESO</th><th>ÓBITO</th><th>TOTAL GERAL</th></tr></thead><tbody>{linhas.map(linha => <tr key={linha.id || linha.inicio}><td>{data(linha.inicio)}</td><td>{data(linha.fim)}</td><td>{linha.dias || '—'}</td><td>{valor(linha.painel, 'cabine')}</td><td>{valor(linha.painel, 'vtr')}</td><td>{valor(linha.painel, 'vultoOutros')}</td><td>{valor(linha.painel, 'preso')}</td><td>{valor(linha.painel, 'obito')}</td><td><strong>{linha.painel.total}</strong></td></tr>)}</tbody></table></div>}</div><ProducaoProcedimentosCorrigida inicio={inicio(mesInicio)} fim={fim(mesFim)} /></section>; }

function Producao() { const [mesInicio, setMesInicio] = useState('2026-04'); const [mesFim, setMesFim] = useState('2026-08'); const [linhas, setLinhas] = useState<any[]>([]); const [carregando, setCarregando] = useState(true); const [erro, setErro] = useState(''); const inicio = (mes: string) => mes + '-01'; const fim = (mes: string) => { const partes = mes.split('-').map(Number); return partes[0] + '-' + String(partes[1]).padStart(2, '0') + '-' + String(new Date(partes[0], partes[1], 0).getDate()).padStart(2, '0'); }; const consultar = async () => { if (!mesInicio || !mesFim || mesInicio > mesFim) { setErro('Selecione um período válido.'); setLinhas([]); setCarregando(false); return; } setCarregando(true); setErro(''); const periodos: any[] = []; const [anoInicial, mesInicial] = mesInicio.split('-').map(Number); const [anoFinal, mesFinal] = mesFim.split('-').map(Number); for (let ano = anoInicial, mes = mesInicial; ano < anoFinal || (ano === anoFinal && mes <= mesFinal); mes += 1) { if (mes > 12) { ano += 1; mes = 1; } const mesTexto = ano + '-' + String(mes).padStart(2, '0'); periodos.push({ inicio: inicio(mesTexto), fim: fim(mesTexto), dias: 0 }); } try { setLinhas(await Promise.all(periodos.map(async periodo => ({ ...periodo, painel: (await api.dashboard({ inicio: periodo.inicio, fim: periodo.fim })).dashboardOperacional })))); } catch (falha: any) { setErro(falha.message || 'Não foi possível consultar o período.'); setLinhas([]); } finally { setCarregando(false); } }; useEffect(() => { consultar(); }, [mesInicio, mesFim]); const data = (valor: string) => { const partes = String(valor || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return partes ? new Date(Number(partes[1]), Number(partes[2]) - 1, Number(partes[3])).toLocaleDateString('pt-BR') : '—'; }; const valor = (painel: any, id: string) => painel?.categorias?.find((item: any) => item.id === id)?.valor ?? '—'; const total = (painel: any) => painel?.total ?? '—'; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Produção operacional</p><h2>Resumo mensal</h2><p>Escolha o mês inicial e o mês final para consultar os indicadores.</p></div><div className="dashboard-filtros"><label>Mês inicial<input type="month" value={mesInicio} onChange={e => setMesInicio(e.target.value)} /></label><label>Mês final<input type="month" value={mesFim} onChange={e => setMesFim(e.target.value)} /></label></div></div><div className="painel tabela-producao">{carregando ? <p className="carregando">Carregando produção...</p> : erro ? <p className="estado-vazio">{erro}</p> : <div className="tabela-producao-scroll"><table><thead><tr><th>DATA INÍCIO</th><th>DATA FINAL</th><th>DIAS TRABALHADOS</th><th>MURALHA</th><th>VTR PM</th><th>VULTO / IMPRENSA / OUTROS</th><th>PRESO</th><th>ÓBITO</th><th>TOTAL GERAL</th></tr></thead><tbody>{linhas.map(linha => <tr key={linha.inicio}><td>{data(linha.inicio)}</td><td>{data(linha.fim)}</td><td>{linha.dias || '—'}</td><td>{valor(linha.painel, 'cabine')}</td><td>{valor(linha.painel, 'vtr')}</td><td>{valor(linha.painel, 'vultoOutros')}</td><td>{valor(linha.painel, 'preso')}</td><td>{valor(linha.painel, 'obito')}</td><td><strong>{total(linha.painel)}</strong></td></tr>)}</tbody></table></div>}</div><ProducaoProcedimentosCorrigida inicio={inicio(mesInicio)} fim={fim(mesFim)} /></section>; }

function TrabalhoFluxo() {
  const [termo, setTermo] = useState(''); const [casos, setCasos] = useState<any[]>([]); const [caso, setCaso] = useState<any>(); const [fotos, setFotos] = useState<any[]>([]);
  useEffect(() => { api.listarCasos().then(setCasos); }, []);
  const buscar = () => api.listarCasos(termo).then(setCasos);
  const selecionar = (id: string) => api.carregarCaso(id).then(c => { setCaso(c); return api.listarFotos(c.id_caso); }).then(setFotos);
  const novoCaso = () => { setCaso({ id_caso: 'NOVO-' + Date.now(), nome_desaparecido: 'Novo caso', talao_pm: '', dados_json: '{}' }); setFotos([]); };
  return <section><div className="cabecalho-secao"><div><p className="eyebrow">Operação</p><h2>Área de trabalho</h2><p>O preenchimento segue a árvore: P0 risco → P1 idade → P2 vulnerabilidade → P3 características.</p></div><button className="primario botao-novo-caso" onClick={novoCaso}>＋ Novo caso</button></div><div className="trabalho"><div className="painel lista"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} onKeyDown={e => e.key === 'Enter' && buscar()} placeholder="Buscar id, talão ou nome" /><button onClick={buscar}>Buscar</button></div>{casos.map(item => <button className="item-caso" key={item.idCaso} onClick={() => selecionar(item.idCaso)}><strong>{item.nome || 'Sem nome'}</strong><span>{item.idCaso} · {item.status || 'Sem status'}</span></button>)}</div><div className="painel arvore">{caso ? <><div className="caso-titulo"><div><h3>{caso.nome_desaparecido || caso.id_caso}</h3><p className="muted">{caso.id_caso} · {caso.talao_pm || 'Talão não informado'}</p></div><button onClick={() => api.adicionarFoto(caso.id_caso).then(() => api.listarFotos(caso.id_caso)).then(setFotos)}>Adicionar foto local</button></div><div className="fotos-local"><strong>Fotos locais: {fotos.length}</strong>{fotos.map(foto => <span key={foto.id}>{JSON.parse(foto.dados_json).nomeArquivo}</span>)}</div><LegacyTriage caso={caso} /></> : <div className="estado-vazio"><h3>Comece um atendimento</h3><p>Clique em “Novo caso” para abrir o fluxo P0.</p></div>}</div></div></section>;
}

function AppFluxo() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{([['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['auditoria', 'Auditoria e correção']] as [Aba, string][]).map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <Dashboard /> : aba === 'trabalho' ? <TrabalhoFluxo /> : <Auditoria />}</main></div>; }
function DashboardPoster() { const [modo, setModo] = useState('legado'); const [inicio, setInicio] = useState('2026-04-22'); const [fim, setFim] = useState('2026-08-14'); const [dados, setDados] = useState<any>(); const hoje = new Date().toISOString().slice(0, 10); const carregar = () => { if (modo === 'legado') return api.dashboard().then(setDados); const final = modo === 'custom' ? fim : hoje; const inicial = modo === 'custom' ? inicio : new Date(Date.now() - Number(modo) * 86400000).toISOString().slice(0, 10); return api.dashboard({ inicio: inicial, fim: final }).then(setDados); }; useEffect(() => { carregar(); }, [modo, inicio, fim]); const dataTexto = (valor: string) => new Date(`${valor}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: '2-digit' }).replace('.', '').toUpperCase(); if (!dados?.dashboardOperacional) return <p className="carregando">Carregando indicadores locais...</p>; const painel = dados.dashboardOperacional; return <section className="dashboard-operacional"><div className="dashboard-filtros"><button className="botao-copiar-painel" onClick={() => undefined}>Copiar painel</button><label>Período<select value={modo} onChange={e => setModo(e.target.value)}><option value="legado">Período legado</option><option value="15">Últimos 15 dias</option><option value="30">Últimos 30 dias</option><option value="custom">Personalizado</option></select></label>{modo === 'custom' && <><label>De<input type="date" value={inicio} onChange={e => setInicio(e.target.value)} /></label><label>Até<input type="date" value={fim} onChange={e => setFim(e.target.value)} /></label></>}</div><div className="poster-dashboard"><header className="poster-cabecalho"><div className="poster-insignia"><img src={logoPMESP} alt="Brasão da Polícia Militar do Estado de São Paulo" /></div><div className="poster-titulo"><h1>RESULTADOS OPERACIONAIS</h1><h2>MURALHA PAULISTA – DESAPARECIDOS</h2></div><div className="poster-copom"><img src={logoCOPOM} alt="Logo COPOM PMESP" /></div><div className="poster-periodo">▣ &nbsp; PERÍODO: <strong>{dataTexto(painel.periodo.inicio)} À {dataTexto(painel.periodo.fim)}</strong></div><div className="poster-subtitulo">POLÍCIA MILITAR DO ESTADO DE SÃO PAULO – COPOM</div></header><section className="poster-total"><strong className="poster-numero">{painel.total}</strong><div className="poster-total-label"><b>TOTAL DE INTERVENÇÕES</b><span>PROCEDIMENTOS OPERACIONAIS<br/>REGISTRADOS NO PERÍODO</span></div><div className="poster-total-nota"><span>TOTAL DE INTERVENÇÕES</span></div></section><section className="poster-distribuicao"><h3>▥ &nbsp; DISTRIBUIÇÃO POR CLASSIFICAÇÃO FINAL</h3><div className="poster-cards">{painel.categorias.map((item: any) => <article className={`poster-card ${item.cor}`} key={item.id}><div className="poster-card-top"><span className="poster-card-icone">◉</span><strong>{item.valor}</strong></div><p>{item.titulo}</p><footer>{item.percentual.toFixed(1).replace('.', ',')}%</footer></article>)}</div></section><footer className="poster-nota"><div className="poster-info">ⓘ<strong>NOTA<br/>TÉCNICA</strong></div><p>As {painel.total} ocorrências apresentadas neste painel tiveram participação operacional da Muralha Paulista - Desaparecidos. O indicador “Localização direta pela equipe Muralha” refere-se exclusivamente aos casos solucionados integralmente pelos teleatendentes/agentes da Muralha, sem depender da localização em campo como elemento principal do resultado final.</p></footer><div className="poster-rodape">POLÍCIA MILITAR DO ESTADO DE SÃO PAULO <span>│</span> COPOM PMESP <span>│</span> PROJETO MURALHA PAULISTA - DESAPARECIDOS</div></div></section>; }
// Listener legado de captura desativado; o listener em fase de captura atualiza o botão e copia o painel.
async function copiarElementoComoImagem(elemento: HTMLElement) { if (!elemento) throw new Error('Painel não encontrado.'); const canvas = await html2canvas(elemento, { backgroundColor: '#050607', scale: 2, useCORS: true, allowTaint: false, logging: false, width: elemento.scrollWidth, height: elemento.scrollHeight, windowWidth: elemento.scrollWidth, windowHeight: elemento.scrollHeight }); const resultado = await (api as any).copiarImagem(canvas.toDataURL('image/png')); if (!resultado || !resultado.ok) throw new Error((resultado && resultado.mensagem) || 'Falha ao copiar painel.'); }
navigator.clipboard.write = async (itens: ClipboardItems) => { const blob = await itens[0].getType('image/png'); const dataUrl = await new Promise<string>((resolve, reject) => { const leitor = new FileReader(); leitor.onload = () => resolve(String(leitor.result)); leitor.onerror = () => reject(new Error('Falha ao preparar imagem.')); leitor.readAsDataURL(blob); }); const resultado = await (api as any).copiarImagem(dataUrl); if (!resultado?.ok) throw new Error(resultado?.mensagem || 'Falha ao copiar painel.'); };
window.addEventListener('click', event => { const alvo = event.target as HTMLElement; if (!alvo?.classList.contains('botao-copiar-painel')) return; alvo.textContent = 'Copiando painel...'; const raiz = alvo.closest('.dashboard-operacional, .resumo-diario'); const elemento = (raiz?.querySelector('.poster-dashboard, .resumo-diario-painel') || document.querySelector('.poster-dashboard, .resumo-diario-painel')) as HTMLElement; copiarElementoComoImagem(elemento).then(() => { alvo.textContent = 'Painel copiado'; setTimeout(() => { alvo.textContent = 'Copiar painel'; }, 1800); }).catch(erro => { alvo.textContent = 'Copiar painel'; window.alert(erro.message || 'Falha ao copiar painel.'); }); }, true);
function ConfiguracoesConexao() { const [config, setConfig] = useState<any>({ modo: 'local', apiBaseUrl: 'http://10.59.186.112' }); const [mensagem, setMensagem] = useState(''); useEffect(() => { api.configuracao().then(setConfig); }, []); const testar = () => api.testarServidor(config).then(resultado => setMensagem(resultado.ok ? 'Servidor conectado e respondendo.' : resultado.mensagem)); const salvar = () => { api.salvarConfiguracao(config).then(nova => { setConfig(nova); setMensagem(nova.modo === 'central' ? 'Modo servidor salvo. As próximas consultas usarão a API central.' : 'Modo local salvo.'); }); }; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Administração</p><h2>Configurações de conexão</h2><p>Defina se este computador usa o banco local ou consulta o servidor central da Cabine Verde.</p></div></div><div className="painel configuracoes-conexao"><label>Modo de operação<select value={config.modo} onChange={e => setConfig({ ...config, modo: e.target.value })}><option value="local">Local — banco deste computador</option><option value="central">Servidor HTTP — dados centralizados</option></select></label><label>Endereço da API central<input value={config.apiBaseUrl || ''} onChange={e => setConfig({ ...config, apiBaseUrl: e.target.value })} placeholder="http://10.59.186.112" /></label><div className="acoes-configuracao"><button onClick={testar}>Testar conexão</button><button className="primario" onClick={salvar}>Salvar configuração</button></div>{mensagem && <p className="mensagem-salvamento">{mensagem}</p>}<div className="aviso-configuracao"><strong>Como funciona</strong><p>O computador servidor mantém a fonte única de dados. Este computador consulta e grava por HTTP; não há sincronização de bancos locais.</p></div></div></section>; }
function AppPainelPrioridadeLegacy() { const [aba, setAba] = useState<Aba>('dashboard'); const [operador, setOperador] = useState<Operador | null>(null); if (!operador) return <Login onEntrar={setOperador} />; const abas: [Aba, string][] = [['dashboard', 'Dashboard'], ['trabalho', 'Área de trabalho'], ['buscar-talao', 'Buscar talão'], ['buscar-imagem', 'Buscar imagem'], ['auditoria', 'Finalização e desfecho']]; return <div className="app"><header className="topo"><div><p className="marca">CABINE VERDE</p><span>{operador.postoGraduacao} {operador.nome} · RE {operador.re} · {operador.equipe}</span></div><span className="status-local">● Banco local ativo</span></header><nav className="abas">{abas.map(([id, label]) => <button className={aba === id ? 'ativa' : ''} onClick={() => setAba(id)} key={id}>{label}</button>)}</nav><main>{aba === 'dashboard' ? <DashboardPoster /> : aba === 'trabalho' ? <TrabalhoPainelPrioridade /> : aba === 'buscar-talao' ? <BuscaTalao /> : aba === 'buscar-imagem' ? <><BuscaImagens /><ConfrontoImagem /></> : <AuditoriaFinal />}</main></div>; }
function EmTriagem({ somenteSemAtividade = false }: { somenteSemAtividade?: boolean }) { const [linhas, setLinhas] = useState<any[]>([]); const [termo, setTermo] = useState(''); const lerDados = (item: any) => { try { return JSON.parse(item.dadosJson || '{}'); } catch { return {}; } }; useEffect(() => { api.listarCasos().then(setLinhas); }, []); const normalizar = (valor: any) => String(valor ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); const valorVerdadeiro = (valor: any) => { if (typeof valor === 'boolean') return valor; return ['sim', 'true', '1', 'realizado', 'concluido', 'concluida'].includes(normalizar(valor)); }; const foiLocalizado = (item: any, dados: any) => /localizado|pres[ao]|obito|morta|morto|encerrado/.test(normalizar(item.status || item.statusCaso || item.statusBanco || dados.statusCaso || dados.resultadoLocalizacao || dados.desfechoCaso)); const temAtividade = (item: any, dados: any) => { const fonte = { ...item, ...dados }; const camposPositivos = ['contatoRealizado', 'pesquisaRealizada', 'fotoRecebida', 'teveMidia', 'teveMidiaFoto', 'qualificacaoRealizada', 'entrevistaRealizada']; if (camposPositivos.some(chave => valorVerdadeiro(fonte[chave]))) return true; return ['respostasArvore', 'complementosArvore', 'qualificacao', 'entrevista', 'pesquisa'].some(chave => fonte[chave] && typeof fonte[chave] === 'object' && Object.values(fonte[chave]).some(valor => String(valor ?? '').trim() !== '')); }; const dataInsercao = (item: any, dados: any) => item.dataInsercao || item.importado_em || dados.dataInsercao || dados.dataCadastro || dados.criadoEm || dados.dataHoraCadastro || ''; const dataOrdenavel = (valor: any) => { const texto = String(valor || ''); const numero = Date.parse(texto); return Number.isNaN(numero) ? Number.MAX_SAFE_INTEGER : numero; }; const filtradas = linhas.filter(item => { const dados = lerDados(item); const atividade = temAtividade(item, dados); return !foiLocalizado(item, dados) && (somenteSemAtividade ? !atividade : atividade) && (!termo || normalizar(JSON.stringify(item)).includes(normalizar(termo))); }).sort((a, b) => dataOrdenavel(dataInsercao(a, lerDados(a))) - dataOrdenavel(dataInsercao(b, lerDados(b)))); const titulo = somenteSemAtividade ? 'Em andamento' : 'Em triagem'; const descricao = somenteSemAtividade ? 'Casos cadastrados como desaparecidos, ainda sem contato, pesquisa ou inserção de foto.' : 'Casos em que o atendimento já começou com contato, pesquisa, entrevista ou foto.'; const vazio = somenteSemAtividade ? 'Nenhum caso em andamento.' : 'Nenhum caso em triagem.'; const formatarData = (valor: any) => { if (!valor) return '—'; const data = new Date(valor); return Number.isNaN(data.getTime()) ? String(valor) : data.toLocaleDateString('pt-BR'); }; return <section><div className="cabecalho-secao"><div><p className="eyebrow">Registro operacional</p><h2>{titulo}</h2><p>{descricao}</p></div></div><div className="painel tabela-producao"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} placeholder="Filtrar por nome, talão ou ocorrência" /></div><div className="tabela-producao-scroll"><table><thead><tr><th>Nº</th><th>DATA DE INSERÇÃO</th><th>TALÃO</th><th>VÍTIMA / CASO</th><th>STATUS</th></tr></thead><tbody>{filtradas.map((item, indice) => <tr key={item.idCaso || item.id_caso || indice}><td>{indice + 1}</td><td>{formatarData(dataInsercao(item, lerDados(item)))}</td><td>{item.talaoPMESP || item.talao_pm || item.talao || '—'}</td><td>{item.nome || item.nome_desaparecido || 'Sem nome'}<small className="muted">{item.idCaso || item.id_caso || ''}</small></td><td>{somenteSemAtividade ? 'Em andamento' : 'Em triagem'}</td></tr>)}</tbody></table></div>{!filtradas.length && <p className="muted">{vazio}</p>}</div></section>; }

function Localizacoes() { const [linhas, setLinhas] = useState<any[]>([]); const [termo, setTermo] = useState(''); const lerDados = (item: any) => { try { return JSON.parse(item.dadosJson || '{}'); } catch { return {}; } }; useEffect(() => { api.listarCasos().then(setLinhas); }, []); const temLocalizacao = (item: any) => { const dados = lerDados(item); const historicoOficial = dados.tipoRegistro === 'HISTORICO_V7' || dados.origemBase === 'V7_ATRIBUICAO_CAUSAL'; const novoLocalizado = !historicoOficial && item.finalizado === true && /LOCALIZADO|LOCALIZADO_CUSTODIA|LOCALIZADO_SEM_VIDA/i.test(String(item.statusCaso || item.statusBanco || item.status || dados.statusCaso || '')); return historicoOficial || novoLocalizado; }; const filtradas = linhas.filter(item => temLocalizacao(item) && (!termo || JSON.stringify(item).toLowerCase().includes(termo.toLowerCase()))); return <section><div className="cabecalho-secao"><div><p className="eyebrow">Registro operacional</p><h2>Localizações</h2><p>254 localizados oficiais até o momento; novos localizados entram após finalização confirmada.</p></div></div><div className="painel tabela-producao"><div className="busca"><input value={termo} onChange={e => setTermo(e.target.value)} placeholder="Filtrar por nome, talão ou ocorrência" /></div><div className="tabela-producao-scroll"><table><thead><tr><th>Nº</th><th>DATA</th><th>TALÃO</th><th>VÍTIMA / CASO</th><th>CIRCUNSTÂNCIAS DA LOCALIZAÇÃO</th><th>LOCALIZAÇÃO / DESFECHO</th><th>IDADE</th><th>SEXO</th></tr></thead><tbody>{filtradas.map((item, indice) => { const dados = lerDados(item); return <tr key={item.idCaso || item.id_caso || indice}><td>{indice + 1}</td><td>{dados.data || dados.dataHoraLocalizacao || item.data_talao || item.dataTalao || item.data || '—'}</td><td>{item.talaoPMESP || item.talao_pm || item.talao || dados.talao || '—'}</td><td>{item.nome || item.nome_desaparecido || dados.nome || 'Sem nome'}</td><td>{dados.circunstancias || dados.observacoesLocalizacao || dados.comoEncontrada || item.observacoes || item.desfecho || '—'}</td><td>{dados.categoria || dados.resultadoLocalizacao || dados.resultado || item.status || '—'}</td><td>{dados.idade || item.idade || '—'}</td><td>{dados.sexo || item.sexo || '—'}</td></tr>; })}</tbody></table></div></div></section>; }
